:root {
  --ink: #08070b;
  --ink-2: #0e0c12;
  --panel: rgba(14, 12, 17, .88);
  --panel-solid: #121017;
  --bone: #e7ddc9;
  --bone-dim: #a69c8b;
  --gold: #c3a063;
  --gold-bright: #e1c48d;
  --gold-dark: #6e5730;
  --blood: #c92e3d;
  --blood-bright: #ff5361;
  --soul: #4fd6bd;
  --violet: #9a6bff;
  --line: rgba(196, 160, 99, .24);
  --line-bright: rgba(214, 181, 116, .5);
  --shadow: 0 24px 80px rgba(0, 0, 0, .72);
  --r-common: #aaa7a1;
  --r-magic: #6f9dff;
  --r-rare: #e8c260;
  --r-legendary: #ff8b42;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: var(--ink); color: var(--bone); }
body {
  font-family: "Spectral", Georgia, serif;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}
button, input { font: inherit; }
button { color: inherit; }
button:focus-visible { outline: 1px solid var(--gold-bright); outline-offset: 3px; }
#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.is-hidden { display: none !important; }

/* ── shared type ─────────────────────────────────────────────────────────── */
.kicker {
  display: block;
  font-family: "Cinzel", serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .36em;
  color: var(--gold);
  text-transform: uppercase;
}
h1, h2, h3 { font-family: "Cinzel", Georgia, serif; font-weight: 700; }
kbd {
  display: inline-block;
  min-width: 18px;
  padding: 1px 5px;
  border: 1px solid rgba(231, 221, 201, .2);
  border-bottom-color: rgba(231, 221, 201, .1);
  border-radius: 3px;
  background: rgba(255, 255, 255, .035);
  color: var(--bone);
  font-family: "Cinzel", serif;
  font-size: 9px;
  letter-spacing: .06em;
  text-align: center;
}
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 46px;
  padding: 0 24px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: transparent;
  color: var(--bone);
  cursor: pointer;
  font-family: "Cinzel", serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .17em;
  text-transform: uppercase;
  transition: .22s ease;
}
.btn:hover { border-color: var(--gold); color: #fff; background: rgba(195, 160, 99, .07); }
.btn-primary {
  border-color: rgba(213, 177, 109, .7);
  background: linear-gradient(180deg, rgba(76, 51, 33, .86), rgba(34, 24, 21, .94));
  color: #f0e6d3;
  box-shadow: inset 0 1px 0 rgba(255, 232, 190, .13), 0 8px 30px rgba(0, 0, 0, .4);
}
.btn-primary:hover {
  background: linear-gradient(180deg, rgba(102, 65, 39, .95), rgba(53, 32, 25, .98));
  box-shadow: inset 0 1px 0 rgba(255, 232, 190, .22), 0 0 28px rgba(201, 46, 61, .16);
}
.btn-large { min-height: 58px; padding: 0 34px; font-size: 13px; }
.btn-ghost { background: rgba(9, 8, 11, .28); }
.btn-text {
  min-height: 36px;
  border-color: transparent;
  color: #786e62;
  font-size: 10px;
}
.btn-text:hover { color: var(--bone); background: transparent; }
.btn-small { min-height: 34px; padding: 0 13px; font-size: 9px; letter-spacing: .12em; }
.btn-ornament { color: var(--gold); font-size: 9px; }

.hud-card {
  border: 1px solid var(--line);
  background: linear-gradient(150deg, rgba(20, 17, 22, .9), rgba(8, 7, 10, .78));
  box-shadow: 0 10px 40px rgba(0, 0, 0, .36), inset 0 1px 0 rgba(255, 255, 255, .035);
  backdrop-filter: blur(8px);
}

/* ── title ──────────────────────────────────────────────────────────────── */
.screen { position: absolute; inset: 0; }
.title-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: max(28px, env(safe-area-inset-top)) 24px max(24px, env(safe-area-inset-bottom));
  background:
    radial-gradient(ellipse at 50% 48%, transparent 0 20%, rgba(7, 6, 9, .12) 46%, rgba(7, 6, 9, .8) 100%),
    linear-gradient(180deg, rgba(7, 6, 9, .16), transparent 34%, transparent 62%, rgba(7, 6, 9, .56));
  text-align: center;
}
.title-screen::before {
  content: "";
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(195, 160, 99, .12);
  pointer-events: none;
  clip-path: polygon(0 0, 46% 0, 47% 1px, 53% 1px, 54% 0, 100% 0, 100% 100%, 54% 100%, 53% calc(100% - 1px), 47% calc(100% - 1px), 46% 100%, 0 100%);
}
.title-topline {
  position: absolute;
  top: max(38px, calc(env(safe-area-inset-top) + 24px));
  display: flex;
  align-items: center;
  gap: 15px;
  color: #9a8a70;
  font-family: "Cinzel", serif;
  font-size: 9px;
  letter-spacing: .38em;
}
.title-mark { color: var(--gold); font-size: 7px; }
.title-lockup { position: relative; display: flex; flex-direction: column; align-items: center; }
.sigil {
  width: 74px;
  height: 74px;
  margin-bottom: 12px;
  color: var(--gold);
  filter: drop-shadow(0 0 16px rgba(201, 46, 61, .28));
  animation: sigil-pulse 5s ease-in-out infinite;
}
.sigil svg { width: 100%; height: 100%; }
@keyframes sigil-pulse { 50% { opacity: .72; transform: scale(.97); } }
.title-lockup .kicker { margin: 0 0 18px; color: #9d7c4c; }
.title-lockup h1 {
  position: relative;
  margin: 0;
  font-size: clamp(66px, 10.3vw, 154px);
  line-height: .82;
  letter-spacing: .045em;
  color: #e9dfcd;
  text-shadow: 0 3px 0 #1c1418, 0 0 50px rgba(207, 179, 129, .08), 0 24px 80px rgba(0, 0, 0, .8);
}
.title-lockup h1::after {
  content: "BLOODMOON";
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(195, 160, 99, .16);
  transform: translateY(4px);
  z-index: -1;
}
.title-lockup h1 span {
  color: #b52c3b;
  text-shadow: 0 0 36px rgba(181, 44, 59, .28), 0 3px 0 #280b10;
}
.title-sub {
  margin: 20px 0 0;
  color: #a99573;
  font-family: "Cinzel", serif;
  font-size: clamp(10px, 1vw, 13px);
  letter-spacing: .78em;
  text-indent: .78em;
}
.title-copy {
  margin: 25px 0 0;
  color: #bdb1a0;
  font-size: clamp(13px, 1.1vw, 16px);
  line-height: 1.7;
  letter-spacing: .025em;
  text-shadow: 0 2px 10px #000;
}
.title-actions { display: flex; align-items: center; gap: 13px; margin-top: 34px; }
.title-features {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: 34px;
  color: #8b8174;
  font-family: "Cinzel", serif;
  font-size: 9px;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.title-features b { margin-right: 5px; color: var(--gold); font-size: 8px; }
.title-features i { width: 3px; height: 3px; border-radius: 50%; background: #6d5d47; }
.title-footer {
  position: absolute;
  bottom: max(53px, calc(env(safe-area-inset-bottom) + 39px));
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  color: #625b52;
  font-size: 10px;
  letter-spacing: .12em;
}
.version-chip {
  position: absolute;
  right: 31px;
  bottom: 28px;
  color: #4d4741;
  font-family: "Cinzel", serif;
  font-size: 7px;
  letter-spacing: .2em;
}

/* ── HUD ────────────────────────────────────────────────────────────────── */
.hud { position: absolute; inset: 0; pointer-events: none; z-index: 10; }
.hud button { pointer-events: auto; }
.hud-top {
  position: absolute;
  top: max(20px, calc(env(safe-area-inset-top) + 12px));
  left: max(20px, calc(env(safe-area-inset-left) + 12px));
  right: max(20px, calc(env(safe-area-inset-right) + 12px));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}
.vitals {
  display: flex;
  align-items: center;
  width: 328px;
  padding: 9px 14px 10px 9px;
  gap: 12px;
  clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 11px 100%, 0 calc(100% - 11px));
}
.portrait {
  position: relative;
  width: 58px;
  height: 62px;
  flex: none;
  border: 1px solid rgba(201, 167, 106, .35);
  background: radial-gradient(circle at 50% 36%, #3b2630, #100c10 72%);
  overflow: visible;
}
.portrait::before { content: ""; position: absolute; inset: 3px; border: 1px solid rgba(255, 255, 255, .055); }
.portrait svg { width: 100%; height: 100%; display: block; }
.level-badge {
  position: absolute;
  left: 50%;
  bottom: -9px;
  transform: translateX(-50%);
  display: grid;
  place-items: center;
  min-width: 32px;
  height: 20px;
  padding: 0 6px;
  border: 1px solid #86663a;
  background: #1b1413;
  color: #efd7a3;
  font-family: "Cinzel", serif;
  font-size: 10px;
  box-shadow: 0 2px 6px #000;
}
.vitals-main { flex: 1; min-width: 0; }
.vitals-label { display: flex; justify-content: space-between; align-items: flex-end; margin: 0 0 5px; }
.vitals-label span:first-child { color: #a58e6c; font-family: "Cinzel", serif; font-size: 8px; letter-spacing: .19em; }
.vitals-label span:last-child { color: #cbbdab; font-size: 10px; letter-spacing: .04em; }
.bar { position: relative; overflow: hidden; background: #080709; border: 1px solid rgba(255, 255, 255, .07); }
.health-bar { height: 15px; background: linear-gradient(180deg, #11080b, #1e0b0f); }
.health-bar .bar-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #6a1019, #b52537 60%, #dc4050);
  box-shadow: 0 0 12px rgba(200, 36, 54, .4);
  transition: width .18s ease;
}
.bar-shine { position: absolute; inset: 0 0 50%; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .12) 42%, transparent); pointer-events: none; }
.xp-row { display: flex; align-items: center; gap: 7px; margin-top: 5px; }
.xp-label { color: #5f9a8d; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .15em; }
.xp-bar { flex: 1; height: 5px; border: 0; background: #07110f; }
.xp-bar .bar-fill { height: 100%; width: 0; background: linear-gradient(90deg, #286e65, #4fd6bd); box-shadow: 0 0 8px rgba(79, 214, 189, .4); }
.xp-row > span:last-child { width: 45px; color: #6b8881; font-size: 8px; text-align: right; }

.run-clock {
  position: absolute;
  left: 50%;
  top: 2px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 210px;
  filter: drop-shadow(0 3px 14px rgba(0, 0, 0, .8));
}
.clock-rule { width: 100%; height: 1px; background: linear-gradient(90deg, transparent, rgba(195, 160, 99, .6), transparent); }
.wave-label { margin-top: 7px; color: var(--gold); font-family: "Cinzel", serif; font-size: 8px; letter-spacing: .34em; }
.timer { margin-top: 1px; color: #e9dfcc; font-family: "Cinzel", serif; font-size: 29px; line-height: 1.1; letter-spacing: .07em; text-shadow: 0 0 22px rgba(220, 185, 122, .12); }
.dawn-label { margin: 2px 0 6px; color: #665b4e; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .19em; }
.hud-tools { display: flex; gap: 7px; }
.icon-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: rgba(10, 8, 12, .8);
  color: #b5a58e;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: .2s;
}
.icon-btn:hover { border-color: var(--gold); color: #fff; background: rgba(30, 23, 21, .9); }
.icon-btn svg { width: 19px; height: 19px; }
.icon-btn .sound-off { display: none; }
.icon-btn.muted .sound-on { display: none; }
.icon-btn.muted .sound-off { display: block; }
.tool-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  display: grid;
  place-items: center;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  border-radius: 50%;
  background: #7e1b27;
  color: #f5e5cc;
  font-family: "Cinzel", serif;
  font-size: 7px;
  border: 1px solid #d58c5a;
}

.objective {
  position: absolute;
  top: 96px;
  left: max(20px, calc(env(safe-area-inset-left) + 12px));
  width: 213px;
  padding: 11px 13px 10px;
  border-left: 2px solid rgba(176, 53, 62, .5);
}
.objective-kicker { display: block; color: #9a474e; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .25em; }
.objective strong { display: block; margin-top: 4px; color: #d5c7b1; font-size: 12px; font-weight: 400; letter-spacing: .03em; }
.objective > span { display: block; margin-top: 2px; color: #72695e; font-size: 9px; }
.objective-track { position: relative; height: 2px; margin-top: 9px; background: rgba(255, 255, 255, .07); }
.objective-track div { height: 100%; width: 0; background: linear-gradient(90deg, #74212b, #d23b4a); transition: width .3s linear; }
.objective-track i { position: absolute; top: -3px; left: 80%; width: 1px; height: 8px; background: rgba(232, 194, 96, .7); }

.run-stats {
  position: absolute;
  right: max(20px, calc(env(safe-area-inset-right) + 12px));
  top: 68px;
  display: flex;
  gap: 16px;
  padding: 7px 12px;
  border-top: 1px solid rgba(195, 160, 99, .14);
  background: linear-gradient(90deg, transparent, rgba(8, 7, 10, .42));
}
.run-stats div { display: flex; align-items: baseline; gap: 5px; }
.run-stats span { color: #5f574e; font-family: "Cinzel", serif; font-size: 6px; letter-spacing: .14em; }
.run-stats strong { color: #b5a486; font-family: "Cinzel", serif; font-size: 11px; font-weight: 600; }

.loot-feed {
  position: absolute;
  right: max(20px, calc(env(safe-area-inset-right) + 12px));
  top: 110px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  width: 255px;
}
.loot-toast {
  --rarity: var(--r-common);
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--rarity) 30%, transparent);
  border-left: 2px solid var(--rarity);
  background: linear-gradient(90deg, rgba(12, 10, 14, .92), rgba(12, 10, 14, .72));
  box-shadow: 0 8px 22px rgba(0, 0, 0, .35);
  animation: toast-in .32s cubic-bezier(.2, .9, .3, 1.2), toast-out .5s 3.5s forwards;
}
.loot-toast .tiny-icon { flex: none; width: 28px; height: 28px; }
.loot-toast .loot-info { flex: 1; min-width: 0; }
.loot-toast .loot-name { display: block; overflow: hidden; color: var(--rarity); font-family: "Cinzel", serif; font-size: 9px; letter-spacing: .06em; text-overflow: ellipsis; white-space: nowrap; }
.loot-toast .loot-meta { display: flex; justify-content: space-between; gap: 7px; color: #756c60; font-size: 8px; }
.loot-toast .up { color: #7bcf9e; }
.loot-toast .down { color: #bd7778; }
@keyframes toast-in { from { opacity: 0; transform: translateX(20px); } }
@keyframes toast-out { to { opacity: 0; transform: translateX(16px); } }

.ability-dock {
  position: absolute;
  right: max(23px, calc(env(safe-area-inset-right) + 15px));
  bottom: max(63px, calc(env(safe-area-inset-bottom) + 52px));
  display: flex;
  align-items: flex-end;
  gap: 11px;
}
.ability-btn {
  --cool: 0%;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 67px;
  height: 67px;
  border: 1px solid rgba(195, 160, 99, .38);
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #2a1a1d, #0a080b 70%);
  color: #d4b77e;
  cursor: pointer;
  box-shadow: 0 5px 22px rgba(0, 0, 0, .55), inset 0 0 18px rgba(195, 160, 99, .06);
  transition: .2s ease;
}
.ability-btn:hover { transform: translateY(-2px); border-color: var(--gold); }
.ability-btn:active { transform: scale(.97); }
.ability-btn::before { content: ""; position: absolute; inset: 5px; border: 1px solid rgba(195, 160, 99, .16); border-radius: 50%; pointer-events: none; }
.ability-art { display: grid; place-items: center; height: 25px; color: #d6ad69; font-family: "Cinzel", serif; font-size: 17px; text-shadow: 0 0 11px rgba(201, 46, 61, .5); }
.nova-art svg { width: 25px; height: 25px; }
.ability-key { position: absolute; top: -7px; right: -3px; display: grid; place-items: center; min-width: 21px; height: 17px; padding: 0 5px; border: 1px solid rgba(195, 160, 99, .3); border-radius: 2px; background: #110d10; color: #8f7d62; font-family: "Cinzel", serif; font-size: 6px; letter-spacing: .05em; }
.ability-name { margin-top: 3px; color: #766b5c; font-family: "Cinzel", serif; font-size: 5.5px; letter-spacing: .1em; }
.ability-cool { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(rgba(0, 0, 0, .68) var(--cool), transparent 0); pointer-events: none; }
.ability-btn.ready { animation: ready-pulse 2.4s ease-in-out infinite; }
@keyframes ready-pulse { 50% { box-shadow: 0 5px 22px rgba(0, 0, 0, .55), inset 0 0 23px rgba(201, 46, 61, .12), 0 0 13px rgba(195, 160, 99, .09); } }

.control-hint {
  position: absolute;
  left: max(23px, calc(env(safe-area-inset-left) + 15px));
  bottom: max(22px, calc(env(safe-area-inset-bottom) + 12px));
  display: flex;
  gap: 15px;
  color: #4e4841;
  font-size: 8px;
  letter-spacing: .06em;
}
.control-hint kbd { margin-right: 3px; opacity: .65; }
.mobile-controls { display: none; }

.boss-bar {
  position: absolute;
  left: 50%;
  bottom: max(54px, calc(env(safe-area-inset-bottom) + 42px));
  transform: translateX(-50%);
  width: min(490px, calc(100vw - 40px));
  padding: 8px 11px 10px;
  border: 1px solid rgba(172, 74, 72, .28);
  background: linear-gradient(180deg, rgba(14, 8, 10, .91), rgba(10, 7, 9, .82));
  box-shadow: 0 12px 35px rgba(0, 0, 0, .5);
  backdrop-filter: blur(5px);
}
.boss-name { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }
.boss-name span { color: #cfb07a; font-family: "Cinzel", serif; font-size: 9px; letter-spacing: .2em; }
.boss-name small { color: #7f4548; font-family: "Cinzel", serif; font-size: 6px; letter-spacing: .19em; }
.boss-bar .bar { height: 8px; background: #15070a; }
.boss-bar .bar-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #611019, #bb2a37, #e0505a); box-shadow: 0 0 14px rgba(201, 46, 61, .4); transition: width .15s; }

/* ── overlay shared ────────────────────────────────────────────────────── */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(ellipse at center, rgba(13, 10, 15, .72), rgba(4, 3, 6, .94));
  backdrop-filter: blur(5px) saturate(.7);
  animation: overlay-in .28s ease both;
}
@keyframes overlay-in { from { opacity: 0; } }
.overlay-grain {
  position: absolute;
  inset: 0;
  opacity: .16;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.34'/%3E%3C/svg%3E");
}
.overlay h2 { margin: 0; font-size: clamp(30px, 4vw, 54px); letter-spacing: .06em; color: #e1d5c1; }
.close-btn {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--line);
  background: transparent;
  color: #8e8170;
  cursor: pointer;
  font-size: 17px;
  transition: .2s;
}
.close-btn:hover { border-color: var(--gold); color: #fff; }

/* ── level up ───────────────────────────────────────────────────────────── */
.levelup-wrap { position: relative; width: min(1040px, 100%); text-align: center; }
.levelup-head .kicker { color: #94474e; }
.levelup-head h2 { margin-top: 8px; font-size: clamp(28px, 4vw, 51px); text-shadow: 0 4px 24px #000; }
.levelup-head p { margin: 10px 0 0; color: #817568; font-size: 13px; }
.levelup-head p span { color: var(--gold-bright); }
.boon-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 17px; margin-top: 35px; }
.boon-card {
  --accent: #b16469;
  position: relative;
  min-height: 282px;
  padding: 26px 22px 22px;
  border: 1px solid rgba(195, 160, 99, .27);
  background:
    linear-gradient(180deg, rgba(27, 21, 25, .94), rgba(10, 8, 12, .97)),
    radial-gradient(circle at 50% 0, rgba(195, 160, 99, .15), transparent 60%);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  transition: transform .22s ease, border-color .22s, box-shadow .22s;
  animation: card-in .4s backwards;
}
.boon-card:nth-child(2) { animation-delay: .07s; }
.boon-card:nth-child(3) { animation-delay: .14s; }
@keyframes card-in { from { opacity: 0; transform: translateY(15px); } }
.boon-card::before {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(195, 160, 99, .09);
  pointer-events: none;
}
.boon-card::after {
  content: "";
  position: absolute;
  top: 0; left: 20%; right: 20%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
}
.boon-card:hover {
  transform: translateY(-7px);
  border-color: color-mix(in srgb, var(--accent) 70%, #c3a063);
  box-shadow: 0 22px 55px rgba(0, 0, 0, .5), 0 0 32px color-mix(in srgb, var(--accent) 12%, transparent);
}
.boon-card.offense { --accent: #d25b5f; }
.boon-card.defense { --accent: #6d9dc5; }
.boon-card.utility { --accent: #6fbf9d; }
.boon-number { position: absolute; top: 17px; right: 16px; color: #4e463e; font-family: "Cinzel", serif; font-size: 10px; }
.boon-icon {
  display: grid;
  place-items: center;
  width: 60px;
  height: 60px;
  margin-bottom: 22px;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent);
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 17%, transparent), transparent 70%);
  color: color-mix(in srgb, var(--accent) 80%, #e6d1a9);
}
.boon-icon svg { width: 34px; height: 34px; }
.boon-type { color: color-mix(in srgb, var(--accent) 72%, #8c8070); font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .23em; text-transform: uppercase; }
.boon-card h3 { margin: 7px 0 8px; color: #e4d7c2; font-size: 20px; letter-spacing: .035em; }
.boon-card p { margin: 0; color: #91877a; font-size: 12px; line-height: 1.55; }
.boon-stack { position: absolute; left: 22px; bottom: 18px; color: #5d5449; font-family: "Cinzel", serif; font-size: 8px; letter-spacing: .11em; }
.boon-stack b { color: #9f8b6c; }
.levelup-hint { margin: 28px 0 0; color: #585149; font-size: 10px; letter-spacing: .06em; }
.levelup-hint kbd { margin: 0 2px; }

/* ── inventory ──────────────────────────────────────────────────────────── */
.inventory-overlay { padding: 24px; }
.sheet {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(1260px, calc(100vw - 48px));
  height: min(770px, calc(100vh - 48px));
  border: 1px solid rgba(195, 160, 99, .31);
  background:
    linear-gradient(140deg, rgba(23, 19, 23, .98), rgba(8, 7, 10, .99)),
    radial-gradient(circle at 45% 0, rgba(195, 160, 99, .08), transparent 45%);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, .04);
}
.sheet::before {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px solid rgba(195, 160, 99, .1);
  pointer-events: none;
}
.sheet-head {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 25px 30px 20px;
  border-bottom: 1px solid rgba(195, 160, 99, .18);
}
.sheet-head::after {
  content: "✦";
  position: absolute;
  left: 50%;
  bottom: -7px;
  padding: 0 8px;
  background: #0e0c11;
  color: #7d6338;
  font-size: 10px;
}
.sheet-head h2 { margin-top: 6px; font-size: clamp(22px, 2.4vw, 34px); }
.sheet-head-right { display: flex; align-items: center; gap: 14px; }
.gold-pill { color: #a9977a; font-size: 11px; letter-spacing: .06em; }
.gold-pill span { color: var(--gold); }
.gold-pill strong { color: #dfc184; font-weight: 400; }
.sheet-body {
  display: grid;
  grid-template-columns: 296px minmax(380px, 1fr) 348px;
  flex: 1;
  min-height: 0;
  padding: 24px 28px 17px;
  gap: 25px;
}
.gear-pane, .bag-pane, .detail-pane { min-height: 0; }
.pane-title { display: flex; align-items: center; gap: 9px; margin-bottom: 13px; color: #9e8e76; font-family: "Cinzel", serif; font-size: 8px; letter-spacing: .22em; }
.pane-title i { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(195, 160, 99, .25), transparent); }
.pane-title em { color: #675d51; font-style: normal; font-size: 7px; letter-spacing: .12em; }
.equipment-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.equip-slot {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  height: 57px;
  padding: 5px 7px;
  border: 1px solid rgba(195, 160, 99, .12);
  background: rgba(255, 255, 255, .018);
  cursor: pointer;
  text-align: left;
  transition: .18s;
}
.equip-slot:hover { border-color: rgba(195, 160, 99, .4); background: rgba(195, 160, 99, .05); }
.equip-slot .slot-meta { min-width: 0; }
.equip-slot .slot-name { display: block; overflow: hidden; color: var(--rarity, #c8b99f); font-family: "Cinzel", serif; font-size: 8px; letter-spacing: .02em; white-space: nowrap; text-overflow: ellipsis; }
.equip-slot .slot-type { display: block; margin-top: 3px; color: #61594e; font-size: 8px; }
.slot-empty { display: flex; align-items: center; justify-content: center; width: 40px; height: 44px; border: 1px dashed rgba(195, 160, 99, .14); color: #4a433a; font-size: 17px; flex: none; }
.stats-pane { margin-top: 20px; }
.stats-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px 14px; }
.stat-row { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid rgba(255, 255, 255, .035); }
.stat-row span { color: #6e6559; font-size: 9px; }
.stat-row strong { color: #bfb19b; font-family: "Cinzel", serif; font-size: 9px; font-weight: 400; }
.stat-row strong.good { color: #7dc09b; }

.bag-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-auto-rows: 1fr;
  gap: 5px;
  max-height: 407px;
}
.bag-cell {
  position: relative;
  aspect-ratio: 1;
  border: 1px solid rgba(195, 160, 99, .1);
  background: rgba(255, 255, 255, .014);
  cursor: default;
  transition: border-color .16s, background .16s;
}
.bag-cell.filled { cursor: pointer; }
.bag-cell.filled:hover { border-color: rgba(195, 160, 99, .5); background: rgba(195, 160, 99, .055); }
.bag-cell.selected { border-color: var(--gold-bright); box-shadow: inset 0 0 0 1px rgba(225, 196, 141, .25), 0 0 17px rgba(195, 160, 99, .08); }
.item-icon {
  --rarity: var(--r-common);
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 55%, color-mix(in srgb, var(--rarity) 13%, transparent), transparent 62%),
    linear-gradient(145deg, rgba(255, 255, 255, .035), rgba(0, 0, 0, .12));
}
.item-icon::before {
  content: "";
  position: absolute;
  inset: 6%;
  border: 1px solid color-mix(in srgb, var(--rarity) 20%, transparent);
  pointer-events: none;
}
.item-icon::after {
  content: "";
  position: absolute;
  left: 12%; right: 12%; top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--rarity), transparent);
  opacity: .7;
}
.item-icon svg { width: 68%; height: 68%; overflow: visible; filter: drop-shadow(0 2px 4px rgba(0, 0, 0, .8)); }
.item-icon.legendary { background: radial-gradient(circle at 50% 55%, rgba(255, 139, 66, .23), transparent 62%), linear-gradient(145deg, rgba(255, 139, 66, .07), rgba(0, 0, 0, .15)); }
.item-icon.legendary::before { border-color: rgba(255, 139, 66, .36); animation: legendary-glow 2.8s ease-in-out infinite; }
@keyframes legendary-glow { 50% { box-shadow: inset 0 0 18px rgba(255, 139, 66, .11), 0 0 10px rgba(255, 139, 66, .07); } }
.bag-cell .item-icon { position: absolute; inset: 1px; width: auto; height: auto; }
.bag-cell .cell-level { position: absolute; right: 3px; bottom: 1px; z-index: 2; color: rgba(220, 208, 188, .42); font-family: "Cinzel", serif; font-size: 6px; }
.bag-cell .upgrade-mark { position: absolute; top: 2px; right: 3px; z-index: 2; color: #75ce9e; font-size: 8px; text-shadow: 0 0 4px #000; }
.bag-cell .item-icon .tiny-icon { width: 60%; height: 60%; }
.bag-cell .empty-plus { color: #39342e; font-size: 11px; }
.bag-footer { display: flex; gap: 6px; margin-top: 14px; }
.loot-legend { display: flex; flex-wrap: wrap; gap: 11px; margin-top: 14px; color: #5f574c; font-family: "Cinzel", serif; font-size: 6px; letter-spacing: .08em; }
.loot-legend span::before { content: "◆"; margin-right: 3px; font-size: 5px; }
.r-common { color: var(--r-common); } .r-magic { color: var(--r-magic); } .r-rare { color: var(--r-rare); } .r-legendary { color: var(--r-legendary); }

.detail-pane {
  display: flex;
  flex-direction: column;
  border-left: 1px solid rgba(195, 160, 99, .15);
  padding-left: 25px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #3e352b transparent;
}
.empty-detail { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; text-align: center; color: #5f574d; }
.empty-sigil { display: grid; place-items: center; width: 50px; height: 50px; margin-bottom: 15px; border: 1px solid rgba(195, 160, 99, .16); border-radius: 50%; color: #75613f; font-size: 19px; }
.empty-detail p { margin: 0; font-size: 13px; }
.empty-detail small { margin-top: 5px; color: #4c453e; font-size: 9px; }

.item-card { --rarity: var(--r-common); }
.item-card-head { display: flex; align-items: flex-start; gap: 13px; }
.item-hero {
  --rarity: var(--r-common);
  width: 66px;
  height: 66px;
  flex: none;
  border: 1px solid color-mix(in srgb, var(--rarity) 46%, transparent);
  background: radial-gradient(circle at 50% 55%, color-mix(in srgb, var(--rarity) 18%, transparent), #0b090d 66%);
  box-shadow: inset 0 0 25px color-mix(in srgb, var(--rarity) 8%, transparent);
}
.item-hero .item-icon { width: 100%; height: 100%; }
.item-title-wrap { min-width: 0; padding-top: 2px; }
.item-name { margin: 0; color: var(--rarity); font-family: "Cinzel", serif; font-size: 17px; font-weight: 700; line-height: 1.18; letter-spacing: .015em; }
.item-sub { margin: 4px 0 0; color: #7b7062; font-size: 10px; }
.item-power { margin-top: 8px; color: #84765f; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .12em; }
.item-power b { color: #c3ab7b; font-weight: 400; }
.item-divider { height: 1px; margin: 15px 0 12px; background: linear-gradient(90deg, rgba(195, 160, 99, .35), transparent); }
.item-implicit { color: #d7cbb6; font-size: 12px; }
.item-implicit strong { color: #f0dfbd; font-weight: 400; }
.affix-list { display: flex; flex-direction: column; gap: 7px; margin: 11px 0 0; }
.affix { color: #78c69b; font-size: 11px; line-height: 1.35; }
.affix b { color: #a4e2bd; font-weight: 400; }
.legendary-power { margin-top: 15px; padding: 11px 12px; border-left: 2px solid var(--r-legendary); background: linear-gradient(90deg, rgba(255, 139, 66, .08), transparent); }
.legendary-power em { display: block; margin-bottom: 3px; color: var(--r-legendary); font-family: "Cinzel", serif; font-size: 7px; font-style: normal; letter-spacing: .15em; }
.legendary-power p { margin: 0; color: #d7a479; font-size: 11px; line-height: 1.4; }
.item-flavor { margin-top: 13px; color: #77695b; font-size: 10px; font-style: italic; line-height: 1.45; }
.compare-block { margin-top: 18px; padding-top: 14px; border-top: 1px solid rgba(195, 160, 99, .17); }
.compare-block h4 { margin: 0 0 7px; color: #8e806d; font-family: "Cinzel", serif; font-size: 7px; font-weight: 400; letter-spacing: .18em; }
.compare-equipped { overflow: hidden; color: var(--rarity); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.compare-stats { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; }
.compare-line { display: flex; justify-content: space-between; font-size: 9px; color: #746a5e; }
.compare-line .buff { color: #79cd9c; }
.compare-line .nerf { color: #c17779; }
.compare-summary { display: flex; align-items: center; justify-content: space-between; margin-top: 12px; padding-top: 9px; border-top: 1px solid rgba(255, 255, 255, .05); }
.compare-summary span { color: #888073; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .12em; }
.compare-summary strong { font-family: "Cinzel", serif; font-size: 13px; font-weight: 400; }
.compare-summary strong.up { color: #7cd19f; }
.compare-summary strong.down { color: #bf7477; }
.item-actions { display: flex; gap: 7px; margin-top: 17px; }
.item-actions .btn { flex: 1; padding: 0 10px; }
.btn-salvage { border-color: rgba(166, 78, 70, .32); color: #a97872; }
.btn-salvage:hover { border-color: #b55a52; color: #e6aaa1; background: rgba(166, 60, 52, .08); }
.sheet-foot { display: flex; justify-content: center; gap: 28px; padding: 10px 15px 13px; border-top: 1px solid rgba(195, 160, 99, .13); color: #5f574c; font-size: 9px; letter-spacing: .03em; }
.sheet-foot kbd { margin-right: 4px; }

/* ── pause / how / end ──────────────────────────────────────────────────── */
.pause-wrap { position: relative; width: min(470px, 100%); text-align: center; }
.pause-wrap .kicker { color: #8d474b; }
.pause-wrap h2 { margin-top: 7px; font-size: 54px; }
.pause-rule { width: 110px; height: 1px; margin: 20px auto 25px; background: linear-gradient(90deg, transparent, var(--gold), transparent); }
.pause-stats { display: flex; justify-content: center; gap: 35px; margin-bottom: 30px; }
.pause-stats div { display: flex; flex-direction: column; gap: 4px; }
.pause-stats span { color: #665e53; font-size: 9px; }
.pause-stats strong { color: #c2b199; font-family: "Cinzel", serif; font-size: 16px; font-weight: 400; }
.pause-actions { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.pause-actions .btn { width: 235px; }
.pause-controls { display: flex; flex-wrap: wrap; justify-content: center; gap: 13px; margin-top: 27px; color: #544d44; font-size: 8px; }
.pause-controls kbd { margin-right: 3px; }

.how-wrap { position: relative; width: min(880px, 100%); text-align: center; }
.how-wrap .kicker { color: #8d474b; }
.how-wrap h2 { margin-top: 8px; font-size: 45px; }
.how-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; margin: 32px 0 27px; text-align: left; }
.how-grid article { padding: 20px 21px; border: 1px solid rgba(195, 160, 99, .15); background: rgba(255, 255, 255, .017); }
.how-grid b { color: #6d5835; font-family: "Cinzel", serif; font-size: 9px; }
.how-grid h3 { margin: 6px 0 5px; color: #cdbca4; font-size: 14px; letter-spacing: .02em; }
.how-grid p { margin: 0; color: #81766a; font-size: 11px; line-height: 1.55; }
.how-grid kbd { margin: 0 2px; }
.how-keys { display: flex; justify-content: center; flex-wrap: wrap; gap: 17px; margin-bottom: 23px; color: #696054; font-size: 9px; }
.how-keys kbd { margin-right: 3px; }

.end-wrap { position: relative; width: min(580px, 100%); text-align: center; }
.end-wrap .kicker { color: #8d474b; }
.end-wrap h2 { margin-top: 8px; font-size: clamp(35px, 5vw, 61px); line-height: 1.04; text-shadow: 0 5px 32px #000; }
#end-copy { margin: 12px 0 0; color: #8c7f6f; font-size: 13px; }
.end-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin: 30px 0 20px; border-top: 1px solid rgba(195, 160, 99, .17); border-bottom: 1px solid rgba(195, 160, 99, .17); }
.end-stats div { padding: 14px 5px; border-right: 1px solid rgba(195, 160, 99, .1); }
.end-stats div:last-child { border-right: 0; }
.end-stats span { display: block; color: #625a50; font-size: 8px; letter-spacing: .09em; }
.end-stats strong { display: block; margin-top: 3px; color: #cdbb9f; font-family: "Cinzel", serif; font-size: 18px; font-weight: 400; }
.end-best { min-height: 63px; }
.best-item { display: inline-flex; align-items: center; gap: 10px; padding: 9px 14px; border: 1px solid rgba(195, 160, 99, .2); background: rgba(255, 255, 255, .018); text-align: left; }
.best-item .item-icon { --rarity: var(--r-common); width: 41px; height: 41px; }
.best-item small { display: block; color: #5e564c; font-family: "Cinzel", serif; font-size: 6px; letter-spacing: .13em; }
.best-item strong { display: block; margin-top: 3px; color: var(--rarity); font-family: "Cinzel", serif; font-size: 12px; font-weight: 400; }
.end-actions { display: flex; flex-direction: column; align-items: center; gap: 8px; margin-top: 20px; }
.end-actions .btn { width: 255px; }
.end-quote { margin-top: 28px; color: #514a42; font-size: 11px; font-style: italic; }

/* ── announcement / toast / flash ───────────────────────────────────────── */
.announcement {
  position: absolute;
  top: 25%;
  left: 50%;
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(640px, 90vw);
  transform: translate(-50%, -10px);
  padding: 21px 30px 19px;
  border-top: 1px solid rgba(195, 160, 99, .36);
  border-bottom: 1px solid rgba(195, 160, 99, .36);
  background: linear-gradient(90deg, transparent, rgba(9, 7, 10, .85) 18%, rgba(9, 7, 10, .85) 82%, transparent);
  text-align: center;
  opacity: 0;
  pointer-events: none;
}
.announcement.show { animation: announce 3.6s ease both; }
@keyframes announce {
  0% { opacity: 0; transform: translate(-50%, 0); }
  12%, 78% { opacity: 1; transform: translate(-50%, -10px); }
  100% { opacity: 0; transform: translate(-50%, -22px); }
}
#announce-kicker { color: #9b4c50; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .32em; }
#announce-title { margin: 7px 0 4px; color: #ddcba9; font-size: clamp(22px, 3vw, 36px); letter-spacing: .1em; text-shadow: 0 3px 20px #000; }
#announce-sub { margin: 0; color: #817467; font-size: 10px; letter-spacing: .05em; }
.announcement.boss #announce-kicker { color: #c9484b; }
.announcement.boss #announce-title { color: #e6a58f; }
.announcement.boss { border-color: rgba(172, 48, 53, .5); }

.toast-layer { position: absolute; left: 50%; bottom: 112px; z-index: 50; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; pointer-events: none; }
.game-toast { padding: 7px 15px; border: 1px solid rgba(195, 160, 99, .2); background: rgba(8, 7, 10, .86); color: #9f9180; font-size: 10px; letter-spacing: .04em; animation: game-toast 2.6s ease forwards; }
@keyframes game-toast { 0% { opacity: 0; transform: translateY(8px); } 12%, 75% { opacity: 1; transform: translateY(0); } 100% { opacity: 0; transform: translateY(-6px); } }
.screen-flash { position: absolute; inset: 0; z-index: 25; background: radial-gradient(ellipse at center, transparent 35%, rgba(145, 17, 28, .28)); opacity: 0; pointer-events: none; transition: opacity .12s; }
.screen-flash.hit { animation: hit-flash .34s ease-out; }
@keyframes hit-flash { 0% { opacity: .8; } 100% { opacity: 0; } }

/* ── responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .sheet-body { grid-template-columns: 260px minmax(300px, 1fr) 308px; gap: 16px; padding: 20px 20px 14px; }
  .sheet-head { padding: 21px 23px 17px; }
  .detail-pane { padding-left: 17px; }
  .vitals { width: 286px; }
}
@media (max-width: 900px) {
  .title-features { display: none; }
  .inventory-overlay { padding: 10px; align-items: stretch; }
  .sheet { width: 100%; height: 100%; overflow-y: auto; }
  .sheet-body { display: flex; flex-direction: column; overflow: visible; padding: 17px; gap: 20px; }
  .gear-pane { flex: none; }
  .equipment-grid { grid-template-columns: repeat(3, 1fr); }
  .bag-grid { max-height: none; grid-template-columns: repeat(6, 1fr); }
  .detail-pane { border-left: 0; border-top: 1px solid rgba(195, 160, 99, .15); padding-left: 0; padding-top: 18px; overflow: visible; min-height: 300px; }
  .empty-detail { min-height: 270px; }
  .sheet-foot { display: none; }
  .sheet-head { position: sticky; top: 0; z-index: 3; background: #0d0b10; }
  .objective { display: none; }
  .run-stats { top: 65px; }
  .control-hint { display: none; }
}
@media (max-width: 760px) {
  .title-screen::before { inset: 9px; }
  .title-topline { top: max(26px, calc(env(safe-area-inset-top) + 16px)); font-size: 7px; }
  .title-lockup .kicker { font-size: 7px; margin-bottom: 13px; letter-spacing: .28em; }
  .title-lockup h1 { font-size: clamp(54px, 17vw, 98px); }
  .title-sub { margin-top: 15px; letter-spacing: .5em; text-indent: .5em; }
  .title-copy { margin-top: 17px; font-size: 12px; }
  .title-actions { flex-direction: column; width: min(320px, 90vw); margin-top: 26px; gap: 7px; }
  .title-actions .btn { width: 100%; }
  .title-footer { bottom: max(25px, calc(env(safe-area-inset-bottom) + 15px)); gap: 6px; font-size: 8px; }
  .title-footer span:nth-child(even) { display: none; }
  .version-chip { display: none; }
  .hud-top { top: max(10px, env(safe-area-inset-top)); left: 10px; right: 10px; }
  .vitals { width: min(250px, calc(100vw - 122px)); padding: 6px 9px 7px 6px; gap: 8px; }
  .portrait { width: 42px; height: 48px; }
  .level-badge { min-width: 24px; height: 16px; font-size: 8px; bottom: -7px; }
  .vitals-label span:first-child { font-size: 6px; }
  .vitals-label span:last-child { font-size: 8px; }
  .health-bar { height: 11px; }
  .xp-row { margin-top: 4px; }
  .xp-label { font-size: 6px; }
  .xp-row > span:last-child { width: 34px; font-size: 7px; }
  .run-clock { top: 1px; min-width: 120px; }
  .timer { font-size: 20px; }
  .wave-label { font-size: 6px; margin-top: 5px; }
  .dawn-label { font-size: 5px; letter-spacing: .1em; }
  .hud-tools { gap: 4px; }
  .icon-btn { width: 32px; height: 32px; }
  .icon-btn svg { width: 15px; height: 15px; }
  .hud-tools .icon-btn:nth-child(2) { display: none; }
  .run-stats { top: 54px; right: 10px; gap: 9px; padding: 4px 8px; }
  .run-stats span { font-size: 5px; }
  .run-stats strong { font-size: 9px; }
  .loot-feed { top: 81px; right: 10px; width: 214px; }
  .loot-toast { padding: 5px 7px; }
  .ability-dock, .control-hint { display: none; }
  .mobile-controls { display: block; }
  .joystick {
    position: absolute;
    left: max(21px, calc(env(safe-area-inset-left) + 14px));
    bottom: max(28px, calc(env(safe-area-inset-bottom) + 19px));
    width: 112px;
    height: 112px;
    border-radius: 50%;
    border: 1px solid rgba(195, 160, 99, .24);
    background: radial-gradient(circle, rgba(195, 160, 99, .05), rgba(8, 7, 10, .28));
    pointer-events: auto;
    touch-action: none;
  }
  .joystick-ring { position: absolute; inset: 17px; border: 1px solid rgba(195, 160, 99, .13); border-radius: 50%; }
  .joystick-knob { position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; margin: -23px 0 0 -23px; border-radius: 50%; border: 1px solid rgba(195, 160, 99, .42); background: radial-gradient(circle at 45% 35%, rgba(121, 93, 67, .55), rgba(22, 16, 19, .8)); box-shadow: 0 5px 15px rgba(0, 0, 0, .45); }
  .mobile-abilities { position: absolute; right: max(21px, calc(env(safe-area-inset-right) + 14px)); bottom: max(30px, calc(env(safe-area-inset-bottom) + 21px)); display: flex; align-items: flex-end; gap: 11px; pointer-events: auto; }
  .mobile-ability { display: grid; place-items: center; width: 62px; height: 62px; border: 1px solid rgba(195, 160, 99, .38); border-radius: 50%; background: radial-gradient(circle at 50% 35%, #2a1a1d, #0a080b 70%); color: #dab673; font-family: "Cinzel", serif; font-size: 18px; touch-action: manipulation; }
  .mobile-ability:active { background: #3d2327; }
  .mobile-ability:first-child { width: 54px; height: 54px; margin-bottom: 60px; font-size: 14px; }
  .boss-bar { bottom: max(15px, env(safe-area-inset-bottom)); width: calc(100vw - 194px); min-width: 150px; left: 47%; }
  .boss-name span { font-size: 7px; letter-spacing: .1em; }
  .boss-name small { display: none; }
  .announcement { top: 19%; padding: 15px 16px; }
  #announce-sub { font-size: 8px; }
  .boon-cards { grid-template-columns: 1fr; gap: 8px; margin-top: 18px; }
  .levelup-wrap { max-height: calc(100vh - 30px); overflow-y: auto; padding: 6px; }
  .levelup-head h2 { font-size: 26px; }
  .levelup-head p { font-size: 11px; }
  .boon-card { display: grid; grid-template-columns: 48px 1fr; grid-template-rows: auto auto; column-gap: 12px; min-height: 0; padding: 14px 15px; align-items: center; }
  .boon-icon { grid-row: 1 / 3; width: 45px; height: 45px; margin: 0; }
  .boon-icon svg { width: 25px; height: 25px; }
  .boon-type, .boon-card h3, .boon-card p { grid-column: 2; }
  .boon-card h3 { margin: 2px 0 2px; font-size: 15px; }
  .boon-card p { font-size: 10px; line-height: 1.3; }
  .boon-stack { display: none; }
  .boon-number { top: 8px; right: 9px; }
  .levelup-hint { margin-top: 13px; font-size: 8px; }
  .how-wrap { max-height: calc(100vh - 30px); overflow-y: auto; padding: 8px; }
  .how-wrap h2 { font-size: 28px; }
  .how-grid { grid-template-columns: 1fr; gap: 7px; margin: 20px 0; }
  .how-grid article { padding: 13px 14px; }
  .how-keys { gap: 10px; font-size: 8px; }
  .pause-wrap h2 { font-size: 39px; }
  .pause-stats { gap: 23px; margin-bottom: 24px; }
  .end-wrap h2 { font-size: 36px; }
  .end-stats { margin: 22px 0 15px; }
  .end-stats strong { font-size: 15px; }
  .toast-layer { bottom: 160px; }
  .sheet-head { padding: 17px 15px 13px; }
  .sheet-head h2 { font-size: 20px; }
  .gold-pill { font-size: 9px; }
  .sheet-body { padding: 13px; }
  .equipment-grid { grid-template-columns: repeat(2, 1fr); }
  .bag-grid { grid-template-columns: repeat(5, 1fr); }
  .bag-footer { flex-wrap: wrap; }
  .detail-pane { min-height: 0; }
  .empty-detail { min-height: 120px; }
  .item-name { font-size: 15px; }
}
@media (max-height: 760px) and (min-width: 761px) {
  .title-lockup h1 { font-size: clamp(56px, 8.8vw, 120px); }
  .title-copy { margin-top: 18px; }
  .title-actions { margin-top: 24px; }
  .title-footer { bottom: 25px; }
  .sigil { width: 54px; height: 54px; margin-bottom: 7px; }
  .title-lockup .kicker { margin-bottom: 12px; }
  .title-sub { margin-top: 14px; }
  .sheet-body { padding-top: 17px; padding-bottom: 10px; }
  .bag-grid { max-height: 340px; }
  .stats-pane { margin-top: 12px; }
  .equipment-grid { gap: 4px; }
  .equip-slot { height: 51px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

