import { TAU } from "./state.js";

const TAU_ = Math.PI * 2;

export function drawShadow(ctx, x, y, rx, ry, alpha = 0.35) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, ry / rx);
  const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
  grad.addColorStop(0, `rgba(0,0,0,${alpha})`);
  grad.addColorStop(0.6, `rgba(0,0,0,${alpha * 0.55})`);
  grad.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(0, 0, rx, 0, TAU_);
  ctx.fill();
  ctx.restore();
}

function glow(ctx, x, y, r, color, alpha = 0.5) {
  const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, color.replace("ALPHA", String(alpha)));
  grad.addColorStop(0.35, color.replace("ALPHA", String(alpha * 0.42)));
  grad.addColorStop(1, color.replace("ALPHA", "0"));
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU_);
  ctx.fill();
}

export function drawPlayer(ctx, p, t) {
  const bob = p.moving ? Math.sin(p.walkPhase * 2.1) * 1.8 : Math.sin(t * 2.1) * 0.6;
  const flicker = p.invuln > 0 && Math.floor(t * 26) % 2 === 0;
  ctx.save();
  ctx.translate(p.x, p.y);
  drawShadow(ctx, 0, 14, 20, 7, 0.48);

  if (p.windrunnerTime > 0) {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, 0, -3, 32, "rgba(103,218,188,ALPHA)", 0.18);
    ctx.restore();
  }

  if (p.dashTime > 0) {
    ctx.globalAlpha = 0.5;
  } else if (flicker) {
    ctx.globalAlpha = 0.55;
  }

  // Swaying cloak behind the body.
  ctx.save();
  const sway = Math.sin(t * 4.1) * 2.2 + (p.moving ? Math.sin(p.walkPhase * 2.3) * 1.8 : 0);
  ctx.fillStyle = "#35151c";
  ctx.beginPath();
  ctx.moveTo(-12, -10);
  ctx.quadraticCurveTo(-17 + sway, 6, -10 + sway * 0.5, 20);
  ctx.lineTo(-2, 13);
  ctx.lineTo(0, 25);
  ctx.lineTo(6, 12);
  ctx.quadraticCurveTo(15 - sway, 2, 12, -9);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(91,35,42,.5)";
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // Legs and boots.
  ctx.strokeStyle = "#1b1419";
  ctx.lineWidth = 5.5;
  ctx.lineCap = "round";
  const leg = p.moving ? Math.sin(p.walkPhase * 2.3) * 3.5 : 0;
  ctx.beginPath();
  ctx.moveTo(-5, 7); ctx.lineTo(-6 - leg, 17);
  ctx.moveTo(5, 7); ctx.lineTo(6 + leg, 17);
  ctx.stroke();
  ctx.strokeStyle = "#4b3b32";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-8 - leg, 16); ctx.lineTo(-4 - leg, 17);
  ctx.moveTo(4 + leg, 16); ctx.lineTo(8 + leg, 17);
  ctx.stroke();

  // Torso leather and mail.
  const torso = ctx.createLinearGradient(-9, -12, 10, 12);
  torso.addColorStop(0, "#463128");
  torso.addColorStop(0.45, "#2a1d1e");
  torso.addColorStop(1, "#151116");
  ctx.fillStyle = torso;
  ctx.beginPath();
  ctx.moveTo(-10, -11 + bob * 0.2);
  ctx.quadraticCurveTo(0, -16, 10, -11 + bob * 0.2);
  ctx.lineTo(8, 8);
  ctx.quadraticCurveTo(0, 12, -8, 8);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(137,105,70,.38)";
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // Chest harness and sigil.
  ctx.strokeStyle = "#765435";
  ctx.lineWidth = 1.7;
  ctx.beginPath();
  ctx.moveTo(-8, -8); ctx.lineTo(6, 5);
  ctx.stroke();
  ctx.strokeStyle = "#a98551";
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.arc(0, -1, 3.4, 0, TAU_);
  ctx.moveTo(0, -5); ctx.lineTo(0, 3);
  ctx.stroke();

  // Shoulders.
  ctx.fillStyle = "#4d3d35";
  ctx.beginPath();
  ctx.ellipse(-9, -9, 5.2, 4.2, -0.4, 0, TAU_);
  ctx.ellipse(9, -9, 5.2, 4.2, 0.4, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#806647";
  ctx.lineWidth = 0.7;
  ctx.stroke();

  // Hood.
  ctx.fillStyle = "#25181c";
  ctx.beginPath();
  ctx.moveTo(-8, -13);
  ctx.quadraticCurveTo(-9, -26, 0, -28);
  ctx.quadraticCurveTo(9, -26, 8, -13);
  ctx.quadraticCurveTo(0, -9, -8, -13);
  ctx.fill();
  ctx.strokeStyle = "#5c3939";
  ctx.stroke();

  // Pale face inside hood.
  const face = ctx.createLinearGradient(0, -24, 0, -15);
  face.addColorStop(0, "#cbb6a4");
  face.addColorStop(1, "#8a6b60");
  ctx.fillStyle = face;
  ctx.beginPath();
  ctx.ellipse(0, -19.5, 4.7, 5.4, 0, 0, TAU_);
  ctx.fill();
  ctx.fillStyle = "#281417";
  ctx.beginPath();
  ctx.ellipse(-2, -20.4, 1, 0.55, 0, 0, TAU_);
  ctx.ellipse(2, -20.4, 1, 0.55, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "rgba(83,43,42,.8)";
  ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-1.3, -16.7); ctx.lineTo(1.3, -16.7);
  ctx.stroke();

  // Hood rim.
  ctx.strokeStyle = "#3a2427";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.arc(0, -18.5, 8, Math.PI * 0.98, Math.PI * 2.02);
  ctx.stroke();

  drawPlayerWeapon(ctx, p, t);

  ctx.restore();

  // Dash afterglow.
  if (p.dashTime > 0) {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, p.x, p.y - 4, 34, "rgba(166,57,66,ALPHA)", 0.18);
    ctx.restore();
  }
}

function drawPlayerWeapon(ctx, p, t) {
  const style = p.weaponStyle || "scythe";
  const swing = p.attackAnim > 0 ? Math.sin((1 - p.attackAnim / 0.22) * Math.PI) : 0;
  ctx.save();
  ctx.translate(3, -5);
  ctx.rotate(p.facing + swing * 0.26);
  if (style === "scythe") {
    ctx.strokeStyle = "#725438";
    ctx.lineWidth = 3.2;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(-10, 7);
    ctx.lineTo(35, -10);
    ctx.stroke();
    ctx.strokeStyle = "#c09a65";
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(-8, 5); ctx.lineTo(34, -11);
    ctx.stroke();
    // Blade.
    ctx.fillStyle = "rgba(158,35,44,.33)";
    ctx.beginPath();
    ctx.arc(35, -11, 16, -2.5, -0.35);
    ctx.arc(35, -11, 11, -0.48, -2.38, true);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#f06b71";
    ctx.lineWidth = 1.8;
    ctx.shadowColor = "#d83744";
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(35, -11, 15, -2.48, -0.42);
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = "#f5d8b1";
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.arc(35, -11, 14, -2.44, -0.48);
    ctx.stroke();
    ctx.fillStyle = "#c8a16b";
    ctx.beginPath();
    ctx.arc(35, -11, 2.2, 0, TAU_);
    ctx.fill();
  } else if (style === "crossbow") {
    ctx.rotate(-0.07);
    ctx.strokeStyle = "#6b5036";
    ctx.lineWidth = 3.2;
    ctx.beginPath();
    ctx.moveTo(-6, 2); ctx.lineTo(24, -2);
    ctx.stroke();
    ctx.strokeStyle = "#b79563";
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(9, 0, 10, -1.8, 1.8);
    ctx.stroke();
    ctx.strokeStyle = "#d9c6a1";
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(12, -9); ctx.lineTo(8, 1); ctx.lineTo(12, 10);
    ctx.stroke();
    ctx.fillStyle = "#f2d5a0";
    ctx.beginPath();
    ctx.moveTo(26, -2); ctx.lineTo(32, -3.5); ctx.lineTo(31, 0.2);
    ctx.closePath();
    ctx.fill();
  } else if (style === "wand") {
    ctx.strokeStyle = "#6e5137";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(-7, 7); ctx.lineTo(19, -10);
    ctx.stroke();
    ctx.strokeStyle = "#b1905d";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-6, 6); ctx.lineTo(18, -9);
    ctx.stroke();
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, 22, -12, 13, "rgba(151,107,255,ALPHA)", 0.5);
    ctx.restore();
    ctx.fillStyle = "#c8a8ff";
    ctx.beginPath();
    ctx.arc(22, -12, 3.2, 0, TAU_);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.beginPath();
    ctx.arc(21, -13, 0.9, 0, TAU_);
    ctx.fill();
  } else {
    ctx.strokeStyle = "#c3b39a";
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(2, -5); ctx.lineTo(16, 6);
    ctx.moveTo(25, -5); ctx.lineTo(10, 6);
    ctx.stroke();
    ctx.fillStyle = "#e7d8b9";
    ctx.beginPath();
    ctx.moveTo(16, 6); ctx.lineTo(21, 11); ctx.lineTo(16, 9); ctx.lineTo(11, 11); ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#aa8f60";
    ctx.beginPath();
    ctx.arc(2, -5, 2, 0, TAU_); ctx.arc(25, -5, 2, 0, TAU_);
    ctx.fill();
  }
  ctx.restore();
}

function drawEnemyHealth(ctx, e) {
  if (!e.elite && !e.boss) return;
  const w = e.boss ? 62 : 38;
  const y = e.y - e.radius - (e.boss ? 34 : 17);
  ctx.save();
  ctx.translate(e.x - w / 2, y);
  ctx.fillStyle = "rgba(0,0,0,.7)";
  ctx.fillRect(0, 0, w, 3);
  ctx.fillStyle = e.boss ? "#e04d50" : "#d1a052";
  ctx.fillRect(0, 0, w * Math.max(0, e.hp / e.maxHp), 3);
  ctx.strokeStyle = "rgba(255,255,255,.15)";
  ctx.strokeRect(-0.5, -0.5, w + 1, 4);
  ctx.restore();
}

export function drawEnemy(ctx, e, t) {
  const angle = e.facing ?? 0;
  const bob = Math.sin(t * (e.type === "bat" ? 12 : 3.2) + e.phase) * (e.type === "bat" ? 3 : 1.1);
  ctx.save();
  ctx.translate(e.x, e.y);

  if (e.elite) {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, 0, 0, e.radius + 19, "rgba(214,164,75,ALPHA)", 0.18 + Math.sin(t * 3 + e.phase) * 0.04);
    ctx.restore();
  }
  if (e.boss) {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, 0, 0, e.radius + 58, "rgba(207,49,55,ALPHA)", 0.22 + Math.sin(t * 2) * 0.04);
    ctx.restore();
  }

  drawShadow(ctx, 0, e.radius * 0.78, e.radius * (e.type === "bat" ? 1.25 : 1.05), e.radius * 0.38, 0.47);

  ctx.translate(0, bob);
  ctx.rotate(angle);
  // Sprites are drawn facing +X.
  if (e.type === "ghoul") drawGhoul(ctx, e, t);
  else if (e.type === "bat") drawBat(ctx, e, t);
  else if (e.type === "skeleton") drawSkeleton(ctx, e, t);
  else if (e.type === "wraith") drawWraith(ctx, e, t);
  else if (e.type === "brute") drawBrute(ctx, e, t);
  else if (e.type === "king") drawKing(ctx, e, t);

  if (e.hitFlash > 0) {
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, 0, 0, e.radius + 8, "rgba(255,228,210,ALPHA)", Math.min(0.45, e.hitFlash * 4));
    ctx.globalCompositeOperation = "source-over";
  }
  ctx.restore();
  drawEnemyHealth(ctx, e);
}

function drawGhoul(ctx, e, t) {
  const stepped = Math.sin(t * 6.4 + e.phase);
  // Hind legs.
  ctx.strokeStyle = "#5d423d";
  ctx.lineWidth = 3.4;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-5, 5); ctx.lineTo(-10, 9 + stepped);
  ctx.moveTo(4, 5); ctx.lineTo(7 + stepped, 10);
  ctx.stroke();
  // Hunched body.
  const grad = ctx.createLinearGradient(-e.radius, -e.radius, e.radius, e.radius);
  grad.addColorStop(0, e.elite ? "#9b8266" : "#8b665c");
  grad.addColorStop(1, e.elite ? "#4e382c" : "#4b3434");
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.ellipse(0, 0, e.radius * 1.08, e.radius * 0.76, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "rgba(25,17,18,.4)";
  ctx.lineWidth = 0.8;
  ctx.stroke();
  // Ribs.
  ctx.strokeStyle = "rgba(196,154,125,.34)";
  ctx.lineWidth = 0.9;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.arc(-1 + i * 3.5, 0.5, 5.5, -1.05, 1.05);
    ctx.stroke();
  }
  // Reaching arms.
  const reach = 1 + Math.sin(t * 5 + e.phase) * 0.12;
  ctx.strokeStyle = "#725149";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(5, -7); ctx.lineTo(14 * reach, -8); ctx.lineTo(18 * reach, -4);
  ctx.moveTo(5, 7); ctx.lineTo(13 * reach, 8); ctx.lineTo(17 * reach, 4);
  ctx.stroke();
  ctx.strokeStyle = "#c8aa8e";
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(18 * reach, -4); ctx.lineTo(21, -5.5);
  ctx.moveTo(17 * reach, 4); ctx.lineTo(20, 5);
  ctx.stroke();
  // Head.
  ctx.fillStyle = "#a38374";
  ctx.beginPath();
  ctx.ellipse(9, 0, 7.2, 6.2, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#4b302f";
  ctx.stroke();
  // Jaw.
  ctx.fillStyle = "#241414";
  ctx.beginPath();
  ctx.ellipse(13.5, 1.2, 3, 2.1, 0.1, 0, TAU_);
  ctx.fill();
  // Eyes.
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, 11, -2.6, 5, "rgba(240,63,66,ALPHA)", 0.8);
  glow(ctx, 11, 2.6, 5, "rgba(240,63,66,ALPHA)", 0.8);
  ctx.restore();
  ctx.fillStyle = "#ffb08d";
  ctx.beginPath();
  ctx.arc(11.5, -2.6, 1.1, 0, TAU_);
  ctx.arc(11.5, 2.6, 1.1, 0, TAU_);
  ctx.fill();
  if (e.elite) {
    ctx.strokeStyle = "#e1b86b";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(4, -8); ctx.lineTo(7, -13); ctx.lineTo(10, -8);
    ctx.stroke();
  }
}

function drawBat(ctx, e, t) {
  const flap = Math.sin(t * 15 + e.phase);
  ctx.fillStyle = "#3d2737";
  ctx.strokeStyle = "#89536a";
  ctx.lineWidth = 0.8;
  // Wings.
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.quadraticCurveTo(-10, -13 * flap, -22, -2);
  ctx.quadraticCurveTo(-14, 0, -10, 8);
  ctx.quadraticCurveTo(-5, 3, 0, 0);
  ctx.moveTo(0, 0);
  ctx.quadraticCurveTo(10, -13 * flap, 22, -2);
  ctx.quadraticCurveTo(14, 0, 10, 8);
  ctx.quadraticCurveTo(5, 3, 0, 0);
  ctx.fill();
  ctx.stroke();
  // Body.
  ctx.fillStyle = "#76445b";
  ctx.beginPath();
  ctx.ellipse(2, 0, 7, 4.5, 0, 0, TAU_);
  ctx.fill();
  // Ears and eyes.
  ctx.fillStyle = "#a05b74";
  ctx.beginPath();
  ctx.moveTo(5, -4); ctx.lineTo(8, -8); ctx.lineTo(8, -2);
  ctx.moveTo(5, 4); ctx.lineTo(8, 8); ctx.lineTo(8, 2);
  ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, 7, 0, 5, "rgba(255,81,107,ALPHA)", 0.7);
  ctx.restore();
  ctx.fillStyle = "#ffd2c0";
  ctx.beginPath();
  ctx.arc(7, -1, 0.9, 0, TAU_);
  ctx.arc(7, 1, 0.9, 0, TAU_);
  ctx.fill();
}

function drawSkeleton(ctx, e, t) {
  const step = Math.sin(t * 5 + e.phase);
  // Legs.
  ctx.strokeStyle = "#bdb094";
  ctx.lineWidth = 2.2;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-3, 4); ctx.lineTo(-7, 11 + step);
  ctx.moveTo(3, 4); ctx.lineTo(7 + step, 11);
  ctx.stroke();
  // Ribcage.
  ctx.strokeStyle = "#cfc2a4";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(0, -7); ctx.lineTo(0, 6);
  for (let i = 0; i < 3; i++) {
    ctx.moveTo(-6 + i, -4 + i * 3);
    ctx.quadraticCurveTo(0, -1 + i * 3, 6 - i, -4 + i * 3);
  }
  ctx.stroke();
  // Arms and bow.
  ctx.strokeStyle = "#b7a98e";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(0, -5); ctx.lineTo(11, -9);
  ctx.moveTo(0, -4); ctx.lineTo(12, 3);
  ctx.stroke();
  ctx.strokeStyle = "#6a5035";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.arc(16, 0, 10, -1.3, 1.3);
  ctx.stroke();
  ctx.strokeStyle = "#ded1b2";
  ctx.lineWidth = 0.55;
  ctx.beginPath();
  ctx.moveTo(18.5, -9.4); ctx.lineTo(13, 0); ctx.lineTo(18.5, 9.4);
  ctx.stroke();
  if (e.shootFlash > 0) {
    ctx.strokeStyle = "rgba(255,210,133,.9)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(14, 0); ctx.lineTo(30, 0);
    ctx.stroke();
  }
  // Skull.
  ctx.fillStyle = "#d9cdb1";
  ctx.beginPath();
  ctx.ellipse(5, 0, 6.4, 6, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#685d4d";
  ctx.stroke();
  ctx.fillStyle = "#211b19";
  ctx.beginPath();
  ctx.ellipse(7, -2.5, 1.7, 1.4, 0, 0, TAU_);
  ctx.ellipse(7, 2.5, 1.7, 1.4, 0, 0, TAU_);
  ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, 8, -2.5, 4, "rgba(245,193,99,ALPHA)", 0.85);
  glow(ctx, 8, 2.5, 4, "rgba(245,193,99,ALPHA)", 0.85);
  ctx.restore();
  if (e.elite) {
    ctx.strokeStyle = "#e1b86b";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(1, -6); ctx.lineTo(4, -12); ctx.lineTo(7, -6);
    ctx.stroke();
  }
}

function drawWraith(ctx, e, t) {
  const drift = Math.sin(t * 2.3 + e.phase) * 2;
  ctx.translate(0, drift);
  ctx.globalAlpha = 0.86;
  // Tattered lower body.
  ctx.fillStyle = "rgba(48,62,88,.72)";
  ctx.beginPath();
  ctx.moveTo(-10, -2);
  ctx.quadraticCurveTo(-13, 10, -7, 19);
  ctx.lineTo(-3, 12);
  ctx.lineTo(1, 23);
  ctx.lineTo(5, 12);
  ctx.lineTo(9, 18);
  ctx.quadraticCurveTo(13, 6, 10, -4);
  ctx.closePath();
  ctx.fill();
  // Body cloak.
  const grad = ctx.createLinearGradient(-10, -13, 10, 11);
  grad.addColorStop(0, "#8898c5");
  grad.addColorStop(0.3, "#4b5879");
  grad.addColorStop(1, "#242c43");
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(-11, 2);
  ctx.quadraticCurveTo(-13, -13, 0, -18);
  ctx.quadraticCurveTo(13, -13, 10, 3);
  ctx.quadraticCurveTo(0, 10, -11, 2);
  ctx.fill();
  // Hood.
  ctx.fillStyle = "#283148";
  ctx.beginPath();
  ctx.arc(0, -10, 8, Math.PI, TAU_);
  ctx.lineTo(7, 0);
  ctx.quadraticCurveTo(0, 4, -7, 0);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "#10131f";
  ctx.beginPath();
  ctx.ellipse(0, -8, 5.4, 5.8, 0, 0, TAU_);
  ctx.fill();
  // Eyes.
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, 0, -8, 12, "rgba(100,235,213,ALPHA)", 0.56);
  ctx.restore();
  ctx.fillStyle = "#a9fff0";
  ctx.beginPath();
  ctx.ellipse(-2.2, -8.5, 1.15, 1.65, 0, 0, TAU_);
  ctx.ellipse(2.2, -8.5, 1.15, 1.65, 0, 0, TAU_);
  ctx.fill();
  // Arms trailing.
  ctx.strokeStyle = "rgba(146,164,205,.5)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-7, -4); ctx.quadraticCurveTo(-16, 3, -12, 9);
  ctx.moveTo(7, -4); ctx.quadraticCurveTo(16, 3, 12, 9);
  ctx.stroke();
  if (e.elite) {
    ctx.strokeStyle = "#e1b86b";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-4, -17); ctx.lineTo(0, -23); ctx.lineTo(4, -17);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

function drawBrute(ctx, e, t) {
  const step = Math.sin(t * 3.8 + e.phase);
  // Legs.
  ctx.strokeStyle = "#4f3430";
  ctx.lineWidth = 7;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-8, 9); ctx.lineTo(-12, 22 + step);
  ctx.moveTo(8, 9); ctx.lineTo(13 + step, 22);
  ctx.stroke();
  // Massive torso.
  const grad = ctx.createRadialGradient(-5, -8, 3, 0, 0, e.radius);
  grad.addColorStop(0, e.elite ? "#a78a64" : "#8d6353");
  grad.addColorStop(0.6, "#5d3e38");
  grad.addColorStop(1, "#2b1c1d");
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.ellipse(0, 0, e.radius * 1.08, e.radius * 0.86, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "rgba(24,13,14,.55)";
  ctx.lineWidth = 1.2;
  ctx.stroke();
  // Belly plates.
  ctx.strokeStyle = "rgba(189,143,104,.22)";
  ctx.lineWidth = 1.2;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.arc(-2, i * 6, 8, -0.8, 0.8);
    ctx.stroke();
  }
  // Arms.
  ctx.strokeStyle = "#6d4a3e";
  ctx.lineWidth = 6.5;
  ctx.beginPath();
  ctx.moveTo(4, -12); ctx.lineTo(18, -18 + step);
  ctx.moveTo(4, 12); ctx.lineTo(18, 18 - step);
  ctx.stroke();
  // Fists.
  ctx.fillStyle = "#9b705d";
  ctx.beginPath();
  ctx.arc(19, -18 + step, 5, 0, TAU_);
  ctx.arc(19, 18 - step, 5, 0, TAU_);
  ctx.fill();
  // Head and horns.
  ctx.fillStyle = "#9b705d";
  ctx.beginPath();
  ctx.ellipse(12, 0, 9, 8, 0, 0, TAU_);
  ctx.fill();
  ctx.fillStyle = "#c3a076";
  ctx.beginPath();
  ctx.moveTo(10, -7); ctx.lineTo(16, -17); ctx.lineTo(20, -5);
  ctx.moveTo(10, 7); ctx.lineTo(16, 17); ctx.lineTo(20, 5);
  ctx.fill();
  ctx.fillStyle = "#2b1616";
  ctx.beginPath();
  ctx.ellipse(17, 0, 4, 3.6, 0, 0, TAU_);
  ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, 16, -3, 5, "rgba(255,89,77,ALPHA)", 0.7);
  glow(ctx, 16, 3, 5, "rgba(255,89,77,ALPHA)", 0.7);
  ctx.restore();
  ctx.fillStyle = "#ffd0a4";
  ctx.beginPath();
  ctx.arc(17, -3, 1.2, 0, TAU_); ctx.arc(17, 3, 1.2, 0, TAU_);
  ctx.fill();
  if (e.elite) {
    ctx.strokeStyle = "#e1b86b";
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.moveTo(5, -9); ctx.lineTo(9, -17); ctx.lineTo(13, -9);
    ctx.stroke();
  }
}

function drawKing(ctx, e, t) {
  const step = Math.sin(t * 2.5 + e.phase);
  // Aura spikes.
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  for (let i = 0; i < 10; i++) {
    const a = t * 0.48 + i * TAU_ / 10;
    const r = e.radius + 18 + Math.sin(t * 2 + i) * 5;
    ctx.strokeStyle = `rgba(228,74,79,${0.12 + Math.sin(t * 2.3 + i) * 0.05})`;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * (e.radius * 0.6), Math.sin(a) * (e.radius * 0.6));
    ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
    ctx.stroke();
  }
  ctx.restore();

  // Robe.
  const robe = ctx.createLinearGradient(-30, -20, 30, 40);
  robe.addColorStop(0, "#40232a");
  robe.addColorStop(0.5, "#24151c");
  robe.addColorStop(1, "#0e0a0e");
  ctx.fillStyle = robe;
  ctx.beginPath();
  ctx.moveTo(-25, -13);
  ctx.quadraticCurveTo(-34, 20, -20, 39);
  ctx.lineTo(-10, 32); ctx.lineTo(0, 43); ctx.lineTo(11, 31); ctx.lineTo(22, 40);
  ctx.quadraticCurveTo(34, 18, 24, -14);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(172,99,75,.3)";
  ctx.lineWidth = 1;
  ctx.stroke();

  // Ribcage armor.
  ctx.fillStyle = "#3b2d2c";
  ctx.beginPath();
  ctx.ellipse(0, -5, 25, 22, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#a98e6d";
  ctx.lineWidth = 1.2;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.arc(-2, i * 6, 13, -0.9, 0.9);
    ctx.stroke();
  }
  // Pauldrons.
  ctx.fillStyle = "#55423a";
  ctx.beginPath();
  ctx.ellipse(-21, -12, 11, 8, -0.3, 0, TAU_);
  ctx.ellipse(21, -12, 11, 8, 0.3, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#c3a268";
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // Arms and great blade.
  ctx.strokeStyle = "#6e4c40";
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(16, -16); ctx.lineTo(31, -4 + step);
  ctx.moveTo(-16, -15); ctx.lineTo(-27, 3 - step);
  ctx.stroke();
  ctx.save();
  ctx.translate(34, -2);
  ctx.rotate(-0.34);
  ctx.strokeStyle = "#65503c";
  ctx.lineWidth = 3.4;
  ctx.beginPath();
  ctx.moveTo(-4, 17); ctx.lineTo(28, -13);
  ctx.stroke();
  ctx.fillStyle = "#d1c0a3";
  ctx.beginPath();
  ctx.moveTo(28, -13); ctx.lineTo(45, -31); ctx.lineTo(34, -7); ctx.lineTo(18, 8);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "#ff6a64";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(28, -13); ctx.lineTo(42, -28);
  ctx.stroke();
  ctx.restore();

  // Skull.
  ctx.fillStyle = "#cbbb9d";
  ctx.beginPath();
  ctx.ellipse(0, -22, 12, 13, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#5c4b3e";
  ctx.stroke();
  // Jaw.
  ctx.fillStyle = "#ad9d83";
  ctx.beginPath();
  ctx.ellipse(0, -10, 8, 4.5, 0, 0, TAU_);
  ctx.fill();
  ctx.strokeStyle = "#3c2e2a";
  ctx.lineWidth = 0.8;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 2.5, -12); ctx.lineTo(i * 2.5, -8);
    ctx.stroke();
  }
  // Eyes.
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, -4.2, -24, 9, "rgba(255,71,68,ALPHA)", 0.9);
  glow(ctx, 4.2, -24, 9, "rgba(255,71,68,ALPHA)", 0.9);
  ctx.restore();
  ctx.fillStyle = "#ffb48f";
  ctx.beginPath();
  ctx.ellipse(-4.2, -24, 2, 2.8, 0, 0, TAU_);
  ctx.ellipse(4.2, -24, 2, 2.8, 0, 0, TAU_);
  ctx.fill();
  // Crown.
  ctx.fillStyle = "#c9a355";
  ctx.strokeStyle = "#f0d38b";
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-12, -31);
  ctx.lineTo(-14, -46); ctx.lineTo(-6, -38); ctx.lineTo(0, -50); ctx.lineTo(6, -38);
  ctx.lineTo(14, -46); ctx.lineTo(12, -31);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = "#8b1c25";
  ctx.beginPath();
  ctx.arc(0, -35, 2, 0, TAU_);
  ctx.fill();
}

export function drawProjectile(ctx, p, t) {
  const ang = Math.atan2(p.vy, p.vx);
  ctx.save();
  ctx.translate(p.x, p.y);
  if (p.type === "crossbow") {
    ctx.rotate(ang);
    ctx.strokeStyle = "rgba(245,220,176,.7)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(-18, 0); ctx.lineTo(6, 0);
    ctx.stroke();
    ctx.strokeStyle = "#a77e50";
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = "#f7e4b8";
    ctx.beginPath();
    ctx.moveTo(10, 0); ctx.lineTo(2, -3); ctx.lineTo(5, 0); ctx.lineTo(2, 3);
    ctx.closePath();
    ctx.fill();
  } else if (p.type === "daggers") {
    ctx.rotate(ang);
    ctx.fillStyle = "#baf5e1";
    ctx.beginPath();
    ctx.moveTo(8, 0); ctx.lineTo(-5, -2.2); ctx.lineTo(-8, 0); ctx.lineTo(-5, 2.2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(98,233,194,.4)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-14, 0); ctx.lineTo(-5, 0);
    ctx.stroke();
  } else if (p.type === "wand") {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    glow(ctx, 0, 0, 16, "rgba(159,116,255,ALPHA)", 0.55);
    ctx.restore();
    ctx.fillStyle = "#dbc6ff";
    ctx.beginPath();
    ctx.arc(0, 0, 3.5, 0, TAU_);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.beginPath();
    ctx.arc(-1, -1, 1.1, 0, TAU_);
    ctx.fill();
    ctx.strokeStyle = "rgba(150,105,255,.3)";
    ctx.lineWidth = 2.2;
    ctx.beginPath();
    ctx.moveTo(-Math.cos(ang) * 16, -Math.sin(ang) * 16);
    ctx.lineTo(0, 0);
    ctx.stroke();
  }
  ctx.restore();
}

export function drawFoeShot(ctx, p, t) {
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.globalCompositeOperation = "lighter";
  glow(ctx, 0, 0, p.r * 3.2, p.color === "bone" ? "rgba(246,220,170,ALPHA)" : "rgba(213,68,78,ALPHA)", 0.5);
  ctx.globalCompositeOperation = "source-over";
  if (p.color === "bone") {
    const ang = Math.atan2(p.vy, p.vx);
    ctx.rotate(ang);
    ctx.strokeStyle = "#e5d7b7";
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(7, 0);
    ctx.stroke();
    ctx.fillStyle = "#f2e5c8";
    ctx.beginPath();
    ctx.moveTo(9, 0); ctx.lineTo(4, -2.5); ctx.lineTo(4, 2.5);
    ctx.closePath();
    ctx.fill();
  } else {
    ctx.fillStyle = "#ffb2ad";
    ctx.beginPath();
    ctx.arc(0, 0, p.r, 0, TAU_);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.beginPath();
    ctx.arc(-1, -1, p.r * 0.4, 0, TAU_);
    ctx.fill();
  }
  ctx.restore();
}

export function drawItemGlyph(ctx, type, x, y, size, color) {
  ctx.save();
  ctx.translate(x, y);
  ctx.strokeStyle = "#d6c7af";
  ctx.fillStyle = "#c7b89f";
  ctx.lineWidth = Math.max(1, size * 0.055);
  ctx.lineCap = "round";
  const s = size / 2;
  if (type === "scythe") {
    ctx.strokeStyle = "#9f8464";
    ctx.lineWidth = size * 0.09;
    ctx.beginPath();
    ctx.moveTo(-s * 0.5, s * 0.75);
    ctx.lineTo(s * 0.5, -s * 0.55);
    ctx.stroke();
    ctx.strokeStyle = color;
    ctx.lineWidth = size * 0.08;
    ctx.beginPath();
    ctx.arc(s * 0.3, -s * 0.45, s * 0.44, -2.3, 0.3);
    ctx.stroke();
  } else if (type === "crossbow") {
    ctx.strokeStyle = "#9f8464";
    ctx.lineWidth = size * 0.09;
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.7); ctx.lineTo(0, s * 0.7);
    ctx.moveTo(-s * 0.72, -s * 0.3); ctx.quadraticCurveTo(0, -s * 0.72, s * 0.72, -s * 0.3);
    ctx.stroke();
    ctx.strokeStyle = "#d8c8ab";
    ctx.lineWidth = size * 0.025;
    ctx.beginPath();
    ctx.moveTo(-s * 0.72, -s * 0.3); ctx.lineTo(0, s * 0.12); ctx.lineTo(s * 0.72, -s * 0.3);
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.95); ctx.lineTo(s * 0.17, -s * 0.55); ctx.lineTo(-s * 0.17, -s * 0.55);
    ctx.closePath();
    ctx.fill();
  } else if (type === "wand") {
    ctx.strokeStyle = "#9f8464";
    ctx.lineWidth = size * 0.09;
    ctx.beginPath();
    ctx.moveTo(-s * 0.55, s * 0.8); ctx.lineTo(s * 0.25, -s * 0.35);
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(s * 0.38, -s * 0.53, s * 0.27, 0, TAU_);
    ctx.fill();
    ctx.strokeStyle = "#e4d1ff";
    ctx.lineWidth = size * 0.02;
    ctx.stroke();
  } else if (type === "daggers") {
    ctx.strokeStyle = "#b9a98e";
    ctx.lineWidth = size * 0.06;
    ctx.beginPath();
    ctx.moveTo(-s * 0.7, s * 0.7); ctx.lineTo(s * 0.25, -s * 0.55);
    ctx.moveTo(s * 0.7, s * 0.7); ctx.lineTo(-s * 0.25, -s * 0.55);
    ctx.stroke();
    ctx.strokeStyle = color;
    ctx.lineWidth = size * 0.035;
    ctx.stroke();
  } else if (type === "helm") {
    ctx.fillStyle = "#726257";
    ctx.beginPath();
    ctx.moveTo(-s * 0.55, s * 0.2);
    ctx.arc(0, 0, s * 0.7, Math.PI, 0);
    ctx.lineTo(s * 0.55, s * 0.45);
    ctx.lineTo(-s * 0.55, s * 0.45);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = color;
    ctx.fillRect(-s * 0.42, s * 0.03, s * 0.84, s * 0.11);
  } else if (type === "chest") {
    ctx.fillStyle = "#6e5a4b";
    ctx.beginPath();
    ctx.moveTo(-s * 0.55, -s * 0.55);
    ctx.lineTo(-s * 0.82, -s * 0.2);
    ctx.lineTo(-s * 0.6, s * 0.1);
    ctx.lineTo(-s * 0.5, s * 0.75);
    ctx.lineTo(s * 0.5, s * 0.75);
    ctx.lineTo(s * 0.6, s * 0.1);
    ctx.lineTo(s * 0.82, -s * 0.2);
    ctx.lineTo(s * 0.55, -s * 0.55);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.lineWidth = size * 0.035;
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.48); ctx.lineTo(0, s * 0.7);
    ctx.stroke();
  } else if (type === "boots") {
    ctx.fillStyle = "#6e5a4b";
    ctx.beginPath();
    ctx.moveTo(-s * 0.5, -s * 0.6);
    ctx.lineTo(-s * 0.12, -s * 0.6);
    ctx.lineTo(-s * 0.12, s * 0.2);
    ctx.quadraticCurveTo(s * 0.7, s * 0.25, s * 0.72, s * 0.7);
    ctx.lineTo(-s * 0.55, s * 0.7);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.lineWidth = size * 0.03;
    ctx.stroke();
  } else if (type === "amulet") {
    ctx.strokeStyle = "#b29462";
    ctx.lineWidth = size * 0.03;
    ctx.beginPath();
    ctx.arc(0, -s * 0.15, s * 0.55, Math.PI * 1.08, Math.PI * 1.92);
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.05);
    ctx.quadraticCurveTo(-s * 0.5, s * 0.25, 0, s * 0.75);
    ctx.quadraticCurveTo(s * 0.5, s * 0.25, 0, -s * 0.05);
    ctx.fill();
  } else if (type === "ring") {
    ctx.strokeStyle = "#c0a063";
    ctx.lineWidth = size * 0.09;
    ctx.beginPath();
    ctx.arc(0, s * 0.22, s * 0.46, 0, TAU_);
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.72); ctx.lineTo(s * 0.28, -s * 0.3); ctx.lineTo(0, -s * 0.05); ctx.lineTo(-s * 0.28, -s * 0.3);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

import { G, WORLD, TAU, clamp, lerp, BOSS_AT } from "./state.js";
import {
  drawPlayer, drawEnemy, drawProjectile, drawFoeShot, drawItemGlyph, drawShadow
} from "./render-entities.js";

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d", { alpha: false });
let viewW = window.innerWidth;
let viewH = window.innerHeight;
let dpr = 1;
let groundPattern = null;
let grainPattern = null;

function buildGround() {
  const tile = document.createElement("canvas");
  tile.width = 512;
  tile.height = 512;
  const g = tile.getContext("2d");
  g.fillStyle = "#131016";
  g.fillRect(0, 0, 512, 512);

  let seed = 991;
  const random = () => {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    return seed / 4294967296;
  };
  // Soft tonal patches.
  for (let i = 0; i < 34; i++) {
    const x = random() * 512;
    const y = random() * 512;
    const r = 20 + random() * 80;
    const grad = g.createRadialGradient(x, y, 0, x, y, r);
    grad.addColorStop(0, `rgba(${random() < 0.5 ? "27,22,29" : "18,16,21"},${0.11 + random() * 0.09})`);
    grad.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = grad;
    g.beginPath();
    g.arc(x, y, r, 0, TAU);
    g.fill();
  }
  // Half-buried flagstones.
  for (let i = 0; i < 105; i++) {
    const x = random() * 512;
    const y = random() * 512;
    const w = 14 + random() * 35;
    const h = 7 + random() * 15;
    g.save();
    g.translate(x, y);
    g.rotate(random() * TAU);
    g.fillStyle = `rgba(${28 + Math.floor(random() * 10)},${24 + Math.floor(random() * 8)},${28 + Math.floor(random() * 10)},${0.5 + random() * 0.3})`;
    g.strokeStyle = "rgba(3,2,5,.55)";
    g.lineWidth = 1;
    g.beginPath();
    g.roundRect(-w / 2, -h / 2, w, h, 2);
    g.fill();
    g.stroke();
    g.strokeStyle = "rgba(120,105,94,.06)";
    g.beginPath();
    g.moveTo(-w / 2 + 2, -h / 2 + 2);
    g.lineTo(w / 2 - 2, -h / 2 + 2);
    g.stroke();
    g.restore();
  }
  // Cracks and roots.
  for (let i = 0; i < 30; i++) {
    let x = random() * 512;
    let y = random() * 512;
    g.strokeStyle = `rgba(4,3,6,${0.35 + random() * 0.3})`;
    g.lineWidth = 0.6 + random() * 0.7;
    g.beginPath();
    g.moveTo(x, y);
    for (let j = 0; j < 3 + Math.floor(random() * 4); j++) {
      x += (random() - 0.5) * 30;
      y += (random() - 0.5) * 30;
      g.lineTo(x, y);
    }
    g.stroke();
  }
  // Gravel and bone flecks.
  for (let i = 0; i < 1500; i++) {
    const a = 0.018 + random() * 0.06;
    g.fillStyle = random() < 0.08 ? `rgba(168,150,127,${a})` : `rgba(0,0,0,${a})`;
    g.fillRect(random() * 512, random() * 512, 1 + random() * 1.4, 1 + random() * 1.4);
  }
  // Moss.
  for (let i = 0; i < 24; i++) {
    const x = random() * 512;
    const y = random() * 512;
    g.fillStyle = `rgba(35,48,39,${0.05 + random() * 0.07})`;
    g.beginPath();
    g.ellipse(x, y, 5 + random() * 20, 2 + random() * 8, random() * TAU, 0, TAU);
    g.fill();
  }
  return tile;
}

function buildGrain() {
  const tile = document.createElement("canvas");
  tile.width = 160;
  tile.height = 160;
  const g = tile.getContext("2d");
  const image = g.createImageData(160, 160);
  for (let i = 0; i < image.data.length; i += 4) {
    const v = Math.random() * 255;
    image.data[i] = v;
    image.data[i + 1] = v;
    image.data[i + 2] = v;
    image.data[i + 3] = Math.random() * 28;
  }
  g.putImageData(image, 0, 0);
  return tile;
}

export function resizeCanvas() {
  viewW = window.innerWidth;
  viewH = window.innerHeight;
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.floor(viewW * dpr);
  canvas.height = Math.floor(viewH * dpr);
  canvas.style.width = `${viewW}px`;
  canvas.style.height = `${viewH}px`;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  if (!groundPattern) groundPattern = ctx.createPattern(buildGround(), "repeat");
  if (!grainPattern) grainPattern = ctx.createPattern(buildGrain(), "repeat");
}

export function renderFrame(t) {
  if (G.mode === "title") {
    drawTitle(t);
  } else {
    drawGame(t);
  }
}

function drawGame(t) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = "#08070b";
  ctx.fillRect(0, 0, viewW, viewH);

  if (!G.player) {
    drawTitle(t);
    return;
  }

  const shake = G.mode === "playing" ? G.shake : 0;
  const sx = (Math.random() - 0.5) * shake;
  const sy = (Math.random() - 0.5) * shake;
  const camX = G.camera.x;
  const camY = G.camera.y;
  const left = camX - viewW / 2 - 100;
  const top = camY - viewH / 2 - 100;

  ctx.save();
  ctx.translate(viewW / 2 - camX + sx, viewH / 2 - camY + sy);

  // World floor.
  ctx.fillStyle = groundPattern;
  ctx.fillRect(left, top, viewW + 200, viewH + 200);

  drawSplotches(camX, camY, t);
  drawRunes(t);
  drawDecals();
  drawCandleLights(t);
  drawProps(t);
  drawGroundLootBeams(t);
  drawPickups(t);

  // Entities depth-sorted.
  const drawables = [];
  for (const enemy of G.enemies) {
    if (isVisible(enemy.x, enemy.y, 100)) drawables.push(enemy);
  }
  drawables.push(G.player);
  drawables.sort((a, b) => a.y - b.y);
  for (const entity of drawables) {
    if (entity === G.player) drawPlayer(ctx, G.player, t);
    else drawEnemy(ctx, entity, t);
  }

  drawProjectiles(t);
  drawEffects(t);
  drawLootLabels();
  drawParticles();
  drawTexts();
  ctx.restore();

  drawAtmosphere(t);
  drawLootFeedGlow();
  if (G.flash > 0) {
    ctx.fillStyle = `rgba(141,20,29,${G.flash * 0.35})`;
    ctx.fillRect(0, 0, viewW, viewH);
  }
  renderGrain();
  if (G.player.hp / G.stats.maxHp < 0.3 && G.mode === "playing") {
    const pulse = 0.05 + Math.sin(t * 4) * 0.025;
    const grad = ctx.createRadialGradient(viewW / 2, viewH / 2, Math.min(viewW, viewH) * 0.32, viewW / 2, viewH / 2, Math.max(viewW, viewH) * 0.7);
    grad.addColorStop(0, "rgba(100,5,13,0)");
    grad.addColorStop(1, `rgba(100,5,13,${pulse})`);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, viewW, viewH);
  }
}

function isVisible(x, y, pad = 60) {
  return x > G.camera.x - viewW / 2 - pad &&
    x < G.camera.x + viewW / 2 + pad &&
    y > G.camera.y - viewH / 2 - pad &&
    y < G.camera.y + viewH / 2 + pad;
}

function drawSplotches(camX, camY, t) {
  const { splotches } = G.decor;
  for (const s of splotches) {
    if (!isVisible(s.x, s.y, 160)) continue;
    ctx.save();
    ctx.translate(s.x, s.y);
    ctx.rotate(s.rot);
    ctx.fillStyle = `rgba(${s.color},${s.alpha})`;
    ctx.beginPath();
    ctx.ellipse(0, 0, s.rx, s.ry, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
  // Thin drifting ground haze.
  if (G.mode === "playing") {
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    for (let i = 0; i < 4; i++) {
      const x = camX + Math.sin(t * 0.035 + i * 2.4) * 300 - 150 + i * 180;
      const y = camY + Math.cos(t * 0.027 + i) * 170;
      const grad = ctx.createRadialGradient(x, y, 0, x, y, 260);
      grad.addColorStop(0, "rgba(86,97,112,.016)");
      grad.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(x, y, 260, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }
}

function drawRunes(t) {
  for (const rune of G.decor.runes) {
    if (!isVisible(rune.x, rune.y, rune.r + 40)) continue;
    const pulse = 0.7 + Math.sin(t * 0.9 + rune.seed) * 0.3;
    ctx.save();
    ctx.translate(rune.x, rune.y);
    ctx.globalCompositeOperation = "lighter";
    const grad = ctx.createRadialGradient(0, 0, rune.r * 0.14, 0, 0, rune.r);
    grad.addColorStop(0, `rgba(127,25,37,${0.03 * pulse})`);
    grad.addColorStop(0.7, `rgba(99,21,32,${0.018 * pulse})`);
    grad.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(0, 0, rune.r, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = `rgba(129,37,43,${0.18 * pulse})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(0, 0, rune.r, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = `rgba(139,57,54,${0.1 * pulse})`;
    ctx.beginPath();
    ctx.arc(0, 0, rune.r * 0.76, 0, TAU);
    ctx.stroke();
    // Glyphs.
    const r = mulberry32Local(rune.seed);
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU + t * 0.006;
      ctx.save();
      ctx.rotate(a);
      ctx.translate(rune.r * 0.87, 0);
      ctx.rotate((r() - 0.5) * 0.7);
      ctx.strokeStyle = `rgba(141,47,49,${0.1 + r() * 0.1})`;
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      ctx.moveTo(-3, -2);
      ctx.lineTo(2, -2);
      ctx.lineTo(-1, 3);
      ctx.lineTo(3, 3);
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }
}

function mulberry32Local(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) | 0;
    let x = Math.imul(a ^ (a >>> 15), 1 | a);
    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

function drawDecals() {
  for (const d of G.decals) {
    if (!isVisible(d.x, d.y, 30)) continue;
    ctx.save();
    ctx.translate(d.x, d.y);
    ctx.rotate(d.rot);
    ctx.fillStyle = `rgba(${d.color},${d.alpha})`;
    ctx.beginPath();
    ctx.ellipse(0, 0, d.rx, d.ry, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
}

function drawCandleLights(t) {
  if (!G.decor) return;
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  for (const prop of G.decor.props) {
    if (prop.kind !== "candle" || !isVisible(prop.x, prop.y, 180)) continue;
    const flicker = 0.8 + Math.sin(t * 8 + prop.seed) * 0.1 + Math.sin(t * 17 + prop.seed * 2) * 0.06;
    const x = prop.x;
    const y = prop.y - 12 * prop.scale;
    const r = (42 + prop.scale * 18) * flicker;
    const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
    grad.addColorStop(0, "rgba(220,126,61,.16)");
    grad.addColorStop(0.4, "rgba(174,75,44,.055)");
    grad.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawProps(t) {
  for (const prop of G.decor.props) {
    if (!isVisible(prop.x, prop.y, 120)) continue;
    drawProp(prop, t);
  }
}

function drawProp(p, t) {
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot);
  ctx.scale(p.scale, p.scale);
  if (p.kind === "grave") {
    drawShadow(ctx, 0, 2, 15, 5, 0.4);
    const grad = ctx.createLinearGradient(0, -34, 0, 3);
    grad.addColorStop(0, "#39333b");
    grad.addColorStop(0.55, "#252128");
    grad.addColorStop(1, "#17151a");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(-10, 1);
    ctx.lineTo(-10, -22);
    ctx.quadraticCurveTo(-10, -35, 0, -37);
    ctx.quadraticCurveTo(10, -35, 10, -22);
    ctx.lineTo(10, 1);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "rgba(119,104,100,.25)";
    ctx.lineWidth = 0.7;
    ctx.stroke();
    ctx.fillStyle = "#111014";
    ctx.fillRect(-13, 0, 26, 4);
    const runeGlow = 0.35 + Math.sin(t * 1.1 + p.seed) * 0.15;
    ctx.strokeStyle = `rgba(142,63,57,${runeGlow})`;
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    if (p.variant % 2 === 0) {
      ctx.moveTo(-4, -23); ctx.lineTo(0, -28); ctx.lineTo(4, -23); ctx.moveTo(0, -28); ctx.lineTo(0, -16);
      ctx.moveTo(-4, -18); ctx.lineTo(4, -20);
    } else {
      ctx.arc(0, -23, 5, 0, TAU);
      ctx.moveTo(0, -18); ctx.lineTo(0, -10);
      ctx.moveTo(-5, -22); ctx.lineTo(5, -22);
    }
    ctx.stroke();
    // Moss.
    ctx.fillStyle = "rgba(44,66,48,.22)";
    ctx.beginPath();
    ctx.ellipse(-6, -2, 5, 2, 0, 0, TAU);
    ctx.fill();
  } else if (p.kind === "cross") {
    drawShadow(ctx, 0, 2, 12, 4, 0.34);
    ctx.strokeStyle = "#2f292e";
    ctx.lineWidth = 4.3;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -36);
    ctx.moveTo(-10, -27); ctx.lineTo(10, -27);
    ctx.stroke();
    ctx.strokeStyle = "rgba(125,110,100,.24)";
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(-1.2, -2); ctx.lineTo(-1.2, -34);
    ctx.moveTo(-10, -28); ctx.lineTo(10, -28);
    ctx.stroke();
  } else if (p.kind === "tree") {
    drawShadow(ctx, 0, 2, 30, 8, 0.35);
    ctx.strokeStyle = "#191419";
    ctx.lineCap = "round";
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(0, 1);
    ctx.quadraticCurveTo(-2, -35, 3, -72);
    ctx.stroke();
    ctx.lineWidth = 3.6;
    ctx.beginPath();
    ctx.moveTo(0, -24); ctx.quadraticCurveTo(-18, -43, -27, -64);
    ctx.moveTo(2, -38); ctx.quadraticCurveTo(19, -50, 26, -70);
    ctx.moveTo(-1, -52); ctx.quadraticCurveTo(-11, -65, -14, -84);
    ctx.stroke();
    ctx.lineWidth = 1.9;
    ctx.beginPath();
    ctx.moveTo(-27, -64); ctx.lineTo(-38, -67);
    ctx.moveTo(-27, -64); ctx.lineTo(-33, -74);
    ctx.moveTo(26, -70); ctx.lineTo(36, -76);
    ctx.moveTo(26, -70); ctx.lineTo(33, -64);
    ctx.moveTo(-14, -84); ctx.lineTo(-23, -92);
    ctx.moveTo(-14, -84); ctx.lineTo(-6, -94);
    ctx.stroke();
    ctx.strokeStyle = "rgba(91,70,61,.18)";
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(1, -5); ctx.quadraticCurveTo(-1, -38, 3, -71);
    ctx.stroke();
    // Roots.
    ctx.strokeStyle = "#191419";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(-13, 5);
    ctx.moveTo(0, 0); ctx.lineTo(11, 6);
    ctx.stroke();
  } else if (p.kind === "candle") {
    drawShadow(ctx, 0, 2, 7, 3, 0.3);
    ctx.fillStyle = "#c0aa86";
    ctx.beginPath();
    ctx.roundRect(-2.3, -10, 4.6, 11, 1.2);
    ctx.fill();
    ctx.fillStyle = "#8d755d";
    ctx.beginPath();
    ctx.ellipse(0, 1, 5.5, 2, 0, 0, TAU);
    ctx.fill();
    const flick = Math.sin(t * 11 + p.seed) * 1.2;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const grad = ctx.createRadialGradient(flick, -13, 0, flick, -13, 9);
    grad.addColorStop(0, "rgba(255,232,176,.9)");
    grad.addColorStop(0.35, "rgba(246,142,63,.4)");
    grad.addColorStop(1, "rgba(246,120,50,0)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(flick, -13, 9, 0, TAU);
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = "#f5c87b";
    ctx.beginPath();
    ctx.ellipse(flick, -13.4, 1.6, 3.2, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#fff3c4";
    ctx.beginPath();
    ctx.ellipse(flick, -14.4, 0.7, 1.4, 0, 0, TAU);
    ctx.fill();
  } else if (p.kind === "rubble") {
    drawShadow(ctx, 0, 1, 12, 4, 0.25);
    ctx.fillStyle = "#252129";
    ctx.strokeStyle = "#40383c";
    ctx.lineWidth = 0.5;
    for (let i = 0; i < 4; i++) {
      const x = -9 + (i * 7) % 18;
      const y = -2 - (i % 3) * 4;
      ctx.beginPath();
      ctx.moveTo(x - 4, 1);
      ctx.lineTo(x - 2, y - 3);
      ctx.lineTo(x + 4, y - 2);
      ctx.lineTo(x + 5, 1);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    }
  } else if (p.kind === "statue") {
    drawShadow(ctx, 0, 2, 17, 6, 0.42);
    ctx.fillStyle = "#211d23";
    ctx.fillRect(-12, -4, 24, 6);
    const grad = ctx.createLinearGradient(0, -44, 0, 0);
    grad.addColorStop(0, "#4b4347");
    grad.addColorStop(1, "#252126");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(-8, -4);
    ctx.quadraticCurveTo(-10, -20, -6, -35);
    ctx.quadraticCurveTo(0, -42, 6, -35);
    ctx.quadraticCurveTo(10, -20, 8, -4);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "#5b5051";
    ctx.beginPath();
    ctx.arc(0, -38, 5.4, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = "rgba(139,111,92,.35)";
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(-4, -34); ctx.quadraticCurveTo(0, -28, 4, -34);
    ctx.stroke();
  } else if (p.kind === "fence") {
    ctx.strokeStyle = "#2a252a";
    ctx.lineWidth = 2;
    for (let i = -3; i <= 3; i++) {
      const h = i === 0 ? 34 : 28;
      ctx.beginPath();
      ctx.moveTo(i * 8, 0); ctx.lineTo(i * 8, -h);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(i * 8 - 2, -h); ctx.lineTo(i * 8, -h - 5); ctx.lineTo(i * 8 + 2, -h);
      ctx.stroke();
    }
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-24, -13); ctx.lineTo(24, -13);
    ctx.moveTo(-24, -23); ctx.lineTo(24, -23);
    ctx.stroke();
  } else if (p.kind === "mushroom") {
    drawShadow(ctx, 0, 1, 7, 2.5, 0.2);
    ctx.fillStyle = "#5d5260";
    ctx.fillRect(-1, -6, 2, 6);
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const grad = ctx.createRadialGradient(0, -7, 0, 0, -7, 10);
    grad.addColorStop(0, "rgba(104,214,190,.24)");
    grad.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(0, -7, 10, 0, TAU);
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = "#4e9a8c";
    ctx.beginPath();
    ctx.ellipse(0, -7, 5.3, 2.8, 0, Math.PI, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawGroundLootBeams(t) {
  for (const loot of G.groundLoot) {
    if (!isVisible(loot.x, loot.y, 100)) continue;
    const item = loot.item;
    const bob = Math.sin(t * 2.2 + loot.phase) * 2.5;
    const color = item.color;
    const rgb = hexToRgb(color);
    const h = item.rarity === "legendary" ? 104 : item.rarity === "rare" ? 76 : item.rarity === "magic" ? 52 : 32;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const grad = ctx.createLinearGradient(loot.x, loot.y + 8, loot.x, loot.y - h);
    grad.addColorStop(0, `rgba(${rgb},0.26)`);
    grad.addColorStop(0.35, `rgba(${rgb},0.08)`);
    grad.addColorStop(1, `rgba(${rgb},0)`);
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(loot.x - 8, loot.y + 7);
    ctx.lineTo(loot.x + 8, loot.y + 7);
    ctx.lineTo(loot.x + 2, loot.y - h);
    ctx.lineTo(loot.x - 2, loot.y - h);
    ctx.closePath();
    ctx.fill();
    const groundGlow = ctx.createRadialGradient(loot.x, loot.y, 0, loot.x, loot.y, 34);
    groundGlow.addColorStop(0, `rgba(${rgb},.16)`);
    groundGlow.addColorStop(1, `rgba(${rgb},0)`);
    ctx.fillStyle = groundGlow;
    ctx.beginPath();
    ctx.ellipse(loot.x, loot.y + 3, 32, 13, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    // Small floating plate.
    const y = loot.y - 13 + bob;
    ctx.save();
    ctx.translate(loot.x, y);
    ctx.fillStyle = "rgba(7,6,9,.88)";
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, -14);
    ctx.lineTo(11, -8);
    ctx.lineTo(13, 1);
    ctx.lineTo(6, 12);
    ctx.lineTo(-7, 12);
    ctx.lineTo(-13, 1);
    ctx.lineTo(-11, -8);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = `rgba(${rgb},.18)`;
    ctx.beginPath();
    ctx.moveTo(0, -11);
    ctx.lineTo(9, -6);
    ctx.lineTo(10, 1);
    ctx.lineTo(4, 9);
    ctx.lineTo(-5, 9);
    ctx.lineTo(-10, 1);
    ctx.lineTo(-9, -6);
    ctx.closePath();
    ctx.stroke();
    drawItemGlyph(ctx, item.icon, 0, -1, 17, color);
    ctx.restore();

    if (item.rarity === "legendary") {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      for (let i = 0; i < 3; i++) {
        const a = t * 1.5 + i * 2.1;
        const x = loot.x + Math.cos(a) * (18 + i * 4);
        const yy = loot.y - 12 + Math.sin(a * 1.3) * 12;
        ctx.fillStyle = `rgba(255,174,99,${0.25 + Math.sin(a * 2) * 0.15})`;
        ctx.beginPath();
        ctx.arc(x, yy, 1.2, 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }
}

function drawLootLabels() {
  for (const loot of G.groundLoot) {
    if (!isVisible(loot.x, loot.y, 90)) continue;
    if (!G.player) continue;
    const d = Math.hypot(loot.x - G.player.x, loot.y - G.player.y);
    if (d > 190) continue;
    const item = loot.item;
    const full = G.bag.length >= 36;
    const label = item.name;
    ctx.save();
    ctx.font = "600 9px Cinzel, Georgia, serif";
    const width = ctx.measureText(label).width + 16;
    const y = loot.y - 48;
    ctx.globalAlpha = clamp(1 - (d - 120) / 90, 0, 1);
    ctx.fillStyle = "rgba(6,5,8,.88)";
    ctx.strokeStyle = item.color;
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.roundRect(loot.x - width / 2, y - 12, width, 22, 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = item.color;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(label, loot.x, y - 2);
    ctx.font = "8px Spectral, Georgia, serif";
    ctx.fillStyle = full ? "#c26f6f" : "#807568";
    ctx.fillText(full ? "Satchel full" : `${item.rarityLabel} ${item.typeLabel}`, loot.x, y + 15);
    ctx.restore();
  }
}

function drawPickups(t) {
  for (const p of G.pickups) {
    if (!isVisible(p.x, p.y, 30)) continue;
    const bob = Math.sin(t * 4 + p.phase) * 1.4;
    ctx.save();
    ctx.translate(p.x, p.y + bob);
    if (p.kind === "xp") {
      ctx.globalCompositeOperation = "lighter";
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 12);
      grad.addColorStop(0, "rgba(79,214,189,.45)");
      grad.addColorStop(1, "rgba(79,214,189,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, 12, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "#8df4df";
      ctx.beginPath();
      ctx.moveTo(0, -5);
      ctx.lineTo(3.5, 0);
      ctx.lineTo(0, 6);
      ctx.lineTo(-3.5, 0);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = "#e4fffa";
      ctx.beginPath();
      ctx.arc(-1, -1, 1.1, 0, TAU);
      ctx.fill();
    } else if (p.kind === "gold") {
      ctx.globalCompositeOperation = "lighter";
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 9);
      grad.addColorStop(0, "rgba(220,174,86,.35)");
      grad.addColorStop(1, "rgba(220,174,86,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, 9, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "#d8b467";
      ctx.beginPath();
      ctx.ellipse(0, 0, 4.2, 5.2, 0.2, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = "#f3d99a";
      ctx.lineWidth = 0.6;
      ctx.stroke();
      ctx.fillStyle = "#755b2e";
      ctx.font = "5px Cinzel, serif";
      ctx.textAlign = "center";
      ctx.fillText("◆", 0, 1.8);
    } else {
      ctx.globalCompositeOperation = "lighter";
      const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 14);
      grad.addColorStop(0, "rgba(221,61,76,.42)");
      grad.addColorStop(1, "rgba(221,61,76,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, 14, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = "source-over";
      ctx.fillStyle = "#d94858";
      ctx.beginPath();
      ctx.moveTo(0, 6);
      ctx.bezierCurveTo(-8, -1, -4, -7, 0, -4);
      ctx.bezierCurveTo(4, -7, 8, -1, 0, 6);
      ctx.fill();
      ctx.fillStyle = "rgba(255,226,210,.75)";
      ctx.beginPath();
      ctx.ellipse(-1.5, -1.5, 1.3, 2, -0.4, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }
}

function drawProjectiles(t) {
  for (const p of G.projectiles) {
    if (isVisible(p.x, p.y, 30)) drawProjectile(ctx, p, t);
  }
  for (const p of G.foeShots) {
    if (isVisible(p.x, p.y, 30)) drawFoeShot(ctx, p, t);
  }
}

function drawEffects(t) {
  for (const e of G.effects) {
    const progress = clamp(e.age / e.life, 0, 1);
    if (e.kind === "slash") {
      ctx.save();
      ctx.translate(e.x, e.y);
      ctx.rotate(e.angle);
      ctx.globalCompositeOperation = "lighter";
      const alpha = (1 - progress) * 0.85;
      ctx.strokeStyle = `rgba(255,75,83,${alpha})`;
      ctx.lineWidth = 7 * (1 - progress) + 1;
      ctx.beginPath();
      ctx.arc(0, 0, e.range * (0.72 + progress * 0.16), -e.arc / 2, e.arc / 2);
      ctx.stroke();
      ctx.strokeStyle = `rgba(255,217,177,${alpha * 0.9})`;
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(0, 0, e.range * (0.75 + progress * 0.18), -e.arc / 2, e.arc / 2);
      ctx.stroke();
      ctx.strokeStyle = `rgba(110,19,33,${alpha * 0.3})`;
      ctx.lineWidth = 15 * (1 - progress);
      ctx.beginPath();
      ctx.arc(0, 0, e.range * (0.66 + progress * 0.15), -e.arc / 2, e.arc / 2);
      ctx.stroke();
      ctx.restore();
    } else if (e.kind === "nova") {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      const r = 25 + e.radius * progress;
      ctx.strokeStyle = `rgba(225,62,72,${(1 - progress) * 0.7})`;
      ctx.lineWidth = 18 * (1 - progress) + 1;
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.stroke();
      ctx.strokeStyle = `rgba(255,207,165,${(1 - progress) * 0.8})`;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.stroke();
      const grad = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, Math.max(10, r));
      grad.addColorStop(0, `rgba(181,28,43,${(1 - progress) * 0.09})`);
      grad.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.fill();
      ctx.restore();
    } else if (e.kind === "ring") {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      ctx.strokeStyle = `rgba(${e.rgb || "188,155,105"},${(1 - progress) * (e.alpha || 0.5)})`;
      ctx.lineWidth = (e.width || 2) * (1 - progress) + 0.5;
      ctx.beginPath();
      ctx.arc(e.x, e.y, e.radius * (0.3 + progress * 0.7), 0, TAU);
      ctx.stroke();
      ctx.restore();
    } else if (e.kind === "explosion") {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      const r = e.radius * (0.3 + progress * 0.8);
      const grad = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, r);
      grad.addColorStop(0, `rgba(255,176,99,${(1 - progress) * 0.28})`);
      grad.addColorStop(0.5, `rgba(177,44,48,${(1 - progress) * 0.16})`);
      grad.addColorStop(1, "rgba(0,0,0,0)");
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(e.x, e.y, r, 0, TAU);
      ctx.fill();
      ctx.restore();
    } else if (e.kind === "afterimage") {
      ctx.save();
      ctx.globalAlpha = (1 - progress) * 0.22;
      ctx.translate(e.x, e.y);
      ctx.fillStyle = "#b52f3c";
      ctx.beginPath();
      ctx.ellipse(0, 0, 12, 23, e.rot || 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    } else if (e.kind === "pillar") {
      ctx.save();
      ctx.globalCompositeOperation = "lighter";
      const alpha = (1 - progress) * 0.45;
      const grad = ctx.createLinearGradient(e.x, e.y + 10, e.x, e.y - e.height);
      grad.addColorStop(0, `rgba(255,80,85,${alpha})`);
      grad.addColorStop(1, "rgba(255,80,85,0)");
      ctx.fillStyle = grad;
      ctx.fillRect(e.x - 5, e.y - e.height, 10, e.height + 10);
      ctx.restore();
    }
  }
}

function drawParticles() {
  const ctx2 = ctx;
  for (const p of G.particles) {
    if (!isVisible(p.x, p.y, 20)) continue;
    const alpha = clamp(p.life / p.maxLife, 0, 1) * (p.alpha ?? 1);
    if (p.kind === "ash") {
      ctx2.fillStyle = `rgba(157,134,119,${alpha * 0.34})`;
      ctx2.beginPath();
      ctx2.arc(p.x, p.y, p.size, 0, TAU);
      ctx2.fill();
    } else if (p.kind === "soul") {
      ctx2.save();
      ctx2.globalCompositeOperation = "lighter";
      ctx2.fillStyle = `rgba(82,225,196,${alpha * 0.55})`;
      ctx2.beginPath();
      ctx2.arc(p.x, p.y, p.size * 2.2, 0, TAU);
      ctx2.fill();
      ctx2.fillStyle = `rgba(200,255,244,${alpha * 0.8})`;
      ctx2.beginPath();
      ctx2.arc(p.x, p.y, p.size * 0.7, 0, TAU);
      ctx2.fill();
      ctx2.restore();
    } else if (p.kind === "smoke") {
      ctx2.fillStyle = `rgba(92,76,93,${alpha * 0.13})`;
      ctx2.beginPath();
      ctx2.arc(p.x, p.y, p.size * (1 + (1 - alpha) * 2.4), 0, TAU);
      ctx2.fill();
    } else if (p.kind === "shard") {
      ctx2.save();
      ctx2.translate(p.x, p.y);
      ctx2.rotate(p.rot + performance.now() * 0.002 * p.spin);
      ctx2.fillStyle = p.color;
      ctx2.globalAlpha = alpha;
      ctx2.beginPath();
      ctx2.moveTo(0, -p.size);
      ctx2.lineTo(p.size * 0.55, 0);
      ctx2.lineTo(0, p.size);
      ctx2.lineTo(-p.size * 0.55, 0);
      ctx2.closePath();
      ctx2.fill();
      ctx2.restore();
    } else {
      if (p.glow) {
        ctx2.save();
        ctx2.globalCompositeOperation = "lighter";
        ctx2.globalAlpha = alpha * 0.5;
        ctx2.fillStyle = p.color;
        ctx2.beginPath();
        ctx2.arc(p.x, p.y, p.size * 2.4, 0, TAU);
        ctx2.fill();
        ctx2.restore();
      }
      ctx2.globalAlpha = alpha;
      ctx2.fillStyle = p.color;
      ctx2.beginPath();
      if (p.streak) {
        ctx2.lineWidth = p.size;
        ctx2.strokeStyle = p.color;
        ctx2.beginPath();
        ctx2.moveTo(p.x - p.vx * 0.018, p.y - p.vy * 0.018);
        ctx2.lineTo(p.x, p.y);
        ctx2.stroke();
      } else {
        ctx2.arc(p.x, p.y, p.size, 0, TAU);
        ctx2.fill();
      }
      ctx2.globalAlpha = 1;
    }
  }
}

function drawTexts() {
  for (const text of G.texts) {
    const alpha = clamp(text.life / text.maxLife, 0, 1);
    const rise = (1 - alpha) * 22;
    ctx.save();
    ctx.globalAlpha = Math.min(1, alpha * 1.8);
    ctx.font = `${text.crit ? "600 18px" : "400 13px"} Spectral, Georgia, serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = text.crit ? 4 : 3;
    ctx.strokeStyle = "rgba(5,4,7,.9)";
    ctx.strokeText(text.value, text.x, text.y - rise);
    ctx.fillStyle = text.color;
    ctx.fillText(text.value, text.x, text.y - rise);
    if (text.crit) {
      ctx.font = "600 7px Cinzel, serif";
      ctx.fillStyle = "rgba(240,184,101,.8)";
      ctx.fillText("CRITICAL", text.x, text.y - rise - 15);
    }
    ctx.restore();
  }
}

function drawAtmosphere(t) {
  // Low drifting mist.
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  for (let i = 0; i < 5; i++) {
    const x = (viewW * (0.15 + i * 0.21) + Math.sin(t * 0.03 + i * 1.7) * 150) % (viewW + 400) - 200;
    const y = viewH * (0.5 + Math.sin(i * 2 + t * 0.02) * 0.24);
    const r = Math.min(viewW, viewH) * (0.25 + (i % 2) * 0.1);
    const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
    grad.addColorStop(0, "rgba(105,119,135,.022)");
    grad.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // Vignette.
  const vignette = ctx.createRadialGradient(viewW / 2, viewH / 2, Math.min(viewW, viewH) * 0.24, viewW / 2, viewH / 2, Math.max(viewW, viewH) * 0.72);
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.72, "rgba(0,0,0,.2)");
  vignette.addColorStop(1, "rgba(0,0,0,.7)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, viewW, viewH);

  // Cold top light and bloody bottom tint.
  const top = ctx.createLinearGradient(0, 0, 0, viewH * 0.5);
  top.addColorStop(0, "rgba(30,29,49,.14)");
  top.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = top;
  ctx.fillRect(0, 0, viewW, viewH * 0.5);
  const bottom = ctx.createLinearGradient(0, viewH * 0.6, 0, viewH);
  bottom.addColorStop(0, "rgba(0,0,0,0)");
  bottom.addColorStop(1, "rgba(35,6,11,.13)");
  ctx.fillStyle = bottom;
  ctx.fillRect(0, viewH * 0.6, viewW, viewH * 0.4);
}

function drawLootFeedGlow() {
  // A faint red bloom in the upper corner where loot cards appear.
  const grad = ctx.createRadialGradient(viewW - 60, 130, 0, viewW - 60, 130, 280);
  grad.addColorStop(0, "rgba(142,45,45,.018)");
  grad.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = grad;
  ctx.fillRect(viewW - 360, 0, 360, 420);
}

function renderGrain() {
  if (!grainPattern) return;
  ctx.save();
  ctx.globalAlpha = 0.22;
  ctx.fillStyle = grainPattern;
  ctx.fillRect(0, 0, viewW, viewH);
  ctx.restore();
}

function hexToRgb(hex) {
  const value = hex.replace("#", "");
  const bigint = parseInt(value.length === 3 ? value.split("").map(c => c + c).join("") : value, 16);
  return `${(bigint >> 16) & 255},${(bigint >> 8) & 255},${bigint & 255}`;
}

/* ── Title scene ─────────────────────────────────────────────────────────── */

function drawTitle(t) {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const w = viewW;
  const h = viewH;
  const sky = ctx.createLinearGradient(0, 0, 0, h);
  sky.addColorStop(0, "#09060e");
  sky.addColorStop(0.38, "#140b13");
  sky.addColorStop(0.68, "#1b0d13");
  sky.addColorStop(1, "#08070a");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, h);

  const mx = w * 0.74;
  const my = h * 0.27;
  const mr = Math.min(w, h) * 0.115;
  // Moon halo.
  const halo = ctx.createRadialGradient(mx, my, mr * 0.25, mx, my, mr * 4.1);
  halo.addColorStop(0, "rgba(192,78,69,.23)");
  halo.addColorStop(0.28, "rgba(137,45,49,.09)");
  halo.addColorStop(0.64, "rgba(92,27,40,.025)");
  halo.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, w, h);

  // Moon disc.
  const moon = ctx.createRadialGradient(mx - mr * 0.28, my - mr * 0.3, mr * 0.1, mx, my, mr);
  moon.addColorStop(0, "#d8896f");
  moon.addColorStop(0.42, "#b34d49");
  moon.addColorStop(0.82, "#7f2a37");
  moon.addColorStop(1, "#5a1b2a");
  ctx.fillStyle = moon;
  ctx.beginPath();
  ctx.arc(mx, my, mr, 0, TAU);
  ctx.fill();
  // Cloud bands across the moon.
  ctx.save();
  ctx.beginPath();
  ctx.arc(mx, my, mr, 0, TAU);
  ctx.clip();
  for (let i = 0; i < 5; i++) {
    const cy = my - mr * 0.5 + i * mr * 0.23 + Math.sin(t * 0.06 + i) * 2;
    const grad = ctx.createLinearGradient(mx - mr, 0, mx + mr, 0);
    grad.addColorStop(0, "rgba(35,13,20,.12)");
    grad.addColorStop(0.5, `rgba(35,13,20,${0.12 + (i % 2) * 0.12})`);
    grad.addColorStop(1, "rgba(35,13,20,.03)");
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.ellipse(mx, cy, mr * (0.95 + i * 0.03), mr * 0.055, 0, 0, TAU);
    ctx.fill();
  }
  // Craters.
  ctx.fillStyle = "rgba(76,25,33,.24)";
  for (let i = 0; i < 7; i++) {
    const a = i * 2.1;
    const rr = mr * (0.18 + (i % 3) * 0.16);
    ctx.beginPath();
    ctx.arc(mx + Math.cos(a) * rr, my + Math.sin(a * 1.4) * rr, mr * (0.04 + (i % 2) * 0.035), 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // Distant mountains and castle.
  drawTitleCastle(w, h, t);

  // Fog at horizon.
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  for (let i = 0; i < 3; i++) {
    const y = h * 0.58 + i * 24;
    const grad = ctx.createLinearGradient(0, y - 60, 0, y + 50);
    grad.addColorStop(0, "rgba(105,115,135,0)");
    grad.addColorStop(0.5, "rgba(104,116,137,.05)");
    grad.addColorStop(1, "rgba(105,115,135,0)");
    ctx.fillStyle = grad;
    ctx.fillRect(0, y - 60, w, 110);
  }
  ctx.restore();

  // Foreground silhouettes: dead trees and graves.
  drawTitleTree(-20, h * 0.84, 1.25, t, 0.8);
  drawTitleTree(w + 24, h * 0.82, -1.08, t, 2.2);
  drawTitleGraves(w, h, t);

  // Ground.
  const ground = ctx.createLinearGradient(0, h * 0.72, 0, h);
  ground.addColorStop(0, "rgba(7,6,9,0)");
  ground.addColorStop(0.34, "rgba(7,6,9,.75)");
  ground.addColorStop(1, "#07060a");
  ctx.fillStyle = ground;
  ctx.fillRect(0, h * 0.68, w, h * 0.32);

  // Ravens.
  drawRavens(w, h, t);

  // Motes.
  for (const mote of G.titleMotes) {
    const x = ((mote.x + mote.vx * t) % 1 + 1) % 1 * w;
    const y = ((mote.y + mote.vy * t) % 1 + 1) % 1 * h;
    const a = 0.15 + (Math.sin(t * 0.7 + mote.phase) * 0.5 + 0.5) * 0.45;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = mote.warm ? `rgba(246,144,82,${a * 0.55})` : `rgba(176,194,187,${a * 0.3})`;
    ctx.beginPath();
    ctx.arc(x, y, mote.size, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // Vignette.
  const vignette = ctx.createRadialGradient(w / 2, h * 0.46, Math.min(w, h) * 0.22, w / 2, h * 0.5, Math.max(w, h) * 0.72);
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.72, "rgba(0,0,0,.14)");
  vignette.addColorStop(1, "rgba(0,0,0,.63)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, w, h);
  renderGrain();
}

function drawTitleCastle(w, h, t) {
  ctx.save();
  const baseY = h * 0.64;
  ctx.fillStyle = "#09070b";
  ctx.beginPath();
  ctx.moveTo(0, baseY + 30);
  ctx.lineTo(0, baseY - 8);
  for (let x = 0; x <= w; x += 26) {
    const hill = Math.sin(x * 0.007 + 1.5) * 18 + Math.sin(x * 0.021) * 8;
    ctx.lineTo(x, baseY - hill);
  }
  ctx.lineTo(w, baseY + 30);
  ctx.closePath();
  ctx.fill();

  // Castle silhouette on the right side.
  const cx = w * 0.77;
  const cy = baseY - 6;
  ctx.fillStyle = "#08060b";
  ctx.beginPath();
  ctx.moveTo(cx - 95, cy);
  ctx.lineTo(cx - 95, cy - 24);
  ctx.lineTo(cx - 76, cy - 24);
  ctx.lineTo(cx - 76, cy - 42);
  ctx.lineTo(cx - 58, cy - 42);
  ctx.lineTo(cx - 58, cy - 28);
  ctx.lineTo(cx - 28, cy - 28);
  ctx.lineTo(cx - 28, cy - 62);
  ctx.lineTo(cx - 9, cy - 78);
  ctx.lineTo(cx + 9, cy - 62);
  ctx.lineTo(cx + 25, cy - 63);
  ctx.lineTo(cx + 25, cy - 30);
  ctx.lineTo(cx + 53, cy - 30);
  ctx.lineTo(cx + 53, cy - 48);
  ctx.lineTo(cx + 72, cy - 48);
  ctx.lineTo(cx + 72, cy - 26);
  ctx.lineTo(cx + 96, cy - 26);
  ctx.lineTo(cx + 96, cy);
  ctx.closePath();
  ctx.fill();

  // Faint windows.
  const flicker = 0.3 + Math.sin(t * 0.9) * 0.08;
  ctx.fillStyle = `rgba(191,110,66,${flicker * 0.4})`;
  ctx.fillRect(cx - 44, cy - 21, 2, 4);
  ctx.fillRect(cx + 18, cy - 44, 2, 5);
  ctx.fillRect(cx + 61, cy - 18, 2, 3);
  ctx.restore();
}

function drawTitleTree(x, baseY, dir, t, phase) {
  ctx.save();
  ctx.translate(x, baseY);
  ctx.scale(dir, 1);
  ctx.strokeStyle = "#070509";
  ctx.lineCap = "round";
  const sway = Math.sin(t * 0.23 + phase) * 0.018;
  ctx.rotate(sway);
  ctx.lineWidth = 14;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.bezierCurveTo(18, -80, -18, -170, 18, -290);
  ctx.stroke();
  ctx.lineWidth = 8;
  ctx.beginPath();
  ctx.moveTo(9, -115);
  ctx.bezierCurveTo(65, -145, 92, -190, 128, -218);
  ctx.moveTo(1, -175);
  ctx.bezierCurveTo(-58, -198, -82, -240, -116, -272);
  ctx.moveTo(16, -245);
  ctx.bezierCurveTo(54, -272, 70, -304, 85, -335);
  ctx.stroke();
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(120, -212); ctx.lineTo(152, -196);
  ctx.moveTo(125, -217); ctx.lineTo(137, -252);
  ctx.moveTo(-108, -265); ctx.lineTo(-146, -281);
  ctx.moveTo(-110, -268); ctx.lineTo(-108, -306);
  ctx.moveTo(82, -330); ctx.lineTo(61, -359);
  ctx.moveTo(84, -333); ctx.lineTo(112, -354);
  ctx.stroke();
  ctx.restore();
}

function drawTitleGraves(w, h, t) {
  const graves = [
    { x: w * 0.12, y: h * 0.88, s: 1.1, tilt: -0.08 },
    { x: w * 0.22, y: h * 0.92, s: 0.7, tilt: 0.08 },
    { x: w * 0.88, y: h * 0.9, s: 0.9, tilt: 0.1 },
    { x: w * 0.78, y: h * 0.95, s: 0.55, tilt: -0.05 },
    { x: w * 0.42, y: h * 0.97, s: 0.64, tilt: 0.03 },
    { x: w * 0.6, y: h * 0.98, s: 0.45, tilt: -0.12 }
  ];
  for (const g of graves) {
    ctx.save();
    ctx.translate(g.x, g.y);
    ctx.rotate(g.tilt);
    ctx.scale(g.s, g.s);
    ctx.fillStyle = "#08060b";
    ctx.beginPath();
    ctx.moveTo(-16, 4);
    ctx.lineTo(-16, -36);
    ctx.quadraticCurveTo(-16, -54, 0, -56);
    ctx.quadraticCurveTo(16, -54, 16, -36);
    ctx.lineTo(16, 4);
    ctx.closePath();
    ctx.fill();
    if (g.s > 0.8) {
      ctx.strokeStyle = `rgba(142,44,49,${0.18 + Math.sin(t * 1.3 + g.x) * 0.06})`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(0, -45); ctx.lineTo(0, -17);
      ctx.moveTo(-6, -37); ctx.lineTo(6, -37);
      ctx.stroke();
    }
    ctx.restore();
  }
}

function drawRavens(w, h, t) {
  const ravens = [
    { x: w * 0.56, y: h * 0.18, s: 1, phase: 1 },
    { x: w * 0.84, y: h * 0.13, s: 0.65, phase: 3.4 },
    { x: w * 0.4, y: h * 0.27, s: 0.55, phase: 5.1 }
  ];
  for (const r of ravens) {
    const flap = Math.sin(t * 2.2 + r.phase);
    const x = r.x + Math.sin(t * 0.08 + r.phase) * 28;
    const y = r.y + Math.cos(t * 0.1 + r.phase) * 12;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(r.s, r.s);
    ctx.strokeStyle = "rgba(6,5,8,.9)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-12, flap * 4);
    ctx.quadraticCurveTo(-5, -5, 0, 0);
    ctx.quadraticCurveTo(5, -5, 12, flap * 4);
    ctx.stroke();
    ctx.restore();
  }
}

import { G } from "./state.js";

export function spawnParticle(x, y, vx, vy, life, size, color, opts = {}) {
  if (G.particles.length > 620) G.particles.shift();
  G.particles.push({
    x, y, vx, vy,
    life, maxLife: life, size, color,
    kind: opts.kind || "spark",
    gravity: opts.gravity || 0,
    drag: opts.drag ?? 0.93,
    glow: opts.glow ?? false,
    streak: opts.streak ?? false,
    alpha: opts.alpha ?? 1,
    rot: opts.rot || 0,
    spin: opts.spin || 0
  });
}

export function burst(x, y, color, count = 8, speed = 90, size = 2, life = 0.5, opts = {}) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const s = speed * (0.35 + Math.random() * 0.8);
    spawnParticle(
      x + (Math.random() - 0.5) * 4,
      y + (Math.random() - 0.5) * 4,
      Math.cos(angle) * s,
      Math.sin(angle) * s,
      life * (0.6 + Math.random() * 0.7),
      size * (0.55 + Math.random() * 0.8),
      color,
      opts
    );
  }
}

export function damageText(x, y, value, color = "#f1e4cf", crit = false) {
  if (G.texts.length > 90) G.texts.shift();
  G.texts.push({
    x: x + (Math.random() - 0.5) * 12,
    y: y - 16,
    value: `${Math.round(value)}`,
    color: crit ? "#ffcf83" : color,
    crit,
    life: crit ? 0.9 : 0.68,
    maxLife: crit ? 0.9 : 0.68
  });
}

export function addEffect(effect) {
  if (G.effects.length > 140) G.effects.shift();
  G.effects.push({ age: 0, ...effect });
}

export function addDecal(x, y, scale = 1, color = "73,17,24", alpha = 0.2) {
  if (G.decals.length > 95) G.decals.shift();
  G.decals.push({
    x: x + (Math.random() - 0.5) * 10,
    y: y + (Math.random() - 0.5) * 8,
    rx: (8 + Math.random() * 12) * scale,
    ry: (3 + Math.random() * 6) * scale,
    rot: Math.random() * Math.PI,
    color, alpha
  });
}

export function screenShake(amount) {
  G.shake = Math.min(18, Math.max(G.shake, amount));
}

export function screenFlash(amount) {
  G.flash = Math.min(1, Math.max(G.flash, amount));
}

import { G } from "./state.js";
import { buildStats } from "./loot.js";

export function recalcStats() {
  const oldMax = G.stats?.maxHp ?? G.player?.hp ?? 100;
  const wasHp = G.player?.hp ?? oldMax;
  G.stats = buildStats(G.equipment, G.boons);
  if (G.player) {
    if (G.stats.maxHp > oldMax) {
      G.player.hp = Math.min(G.stats.maxHp, wasHp + (G.stats.maxHp - oldMax));
    } else {
      G.player.hp = Math.min(wasHp, G.stats.maxHp);
    }
  }
  if (G.player && G.equipment.weapon?.weapon) {
    G.player.weaponStyle = G.equipment.weapon.weapon.style;
  }
  return G.stats;
}

import { G, BAG_SIZE, clamp } from "./state.js";
import { createItemForDrop, comparisonFor } from "./loot.js";
import { recalcStats } from "./player-stats.js";
import { sound } from "./audio-instance.js";
import { lootToast, showToast } from "./ui.js";
import { burst, addEffect, addDecal, spawnParticle, screenShake } from "./fx.js";

export function spawnGear(x, y, source = "normal", forcedRarity = null) {
  const item = createItemForDrop(G.time, G.stats?.luck || 0, source);
  if (forcedRarity) item.rarity = forcedRarity;
  G.groundLoot.push({
    x: x + (Math.random() - 0.5) * 22,
    y: y + (Math.random() - 0.5) * 14,
    item,
    phase: Math.random() * Math.PI * 2,
    age: 0
  });
  if (item.rarity === "legendary" || item.rarity === "rare") {
    addEffect({ kind: "pillar", x, y, height: item.rarity === "legendary" ? 150 : 90, life: 1.1 });
    burst(x, y - 4, item.color, 10, 55, 1.8, 0.9, { glow: true });
  }
  return item;
}

export function spawnEnemyRewards(e) {
  const luck = G.stats?.luck || 0;
  const xpValue = Math.max(1, Math.round(e.xp));
  G.pickups.push({
    kind: "xp", x: e.x + (Math.random() - 0.5) * 12, y: e.y + (Math.random() - 0.5) * 10,
    value: xpValue, phase: Math.random() * 7, vx: (Math.random() - 0.5) * 30, vy: (Math.random() - 0.5) * 30
  });

  if (Math.random() < 0.36) {
    G.pickups.push({
      kind: "gold", x: e.x + (Math.random() - 0.5) * 18, y: e.y + (Math.random() - 0.5) * 14,
      value: Math.max(1, Math.round((1 + Math.random() * 4) * (1 + G.time / 140) * (e.elite ? 4 : 1))),
      phase: Math.random() * 7, vx: (Math.random() - 0.5) * 30, vy: (Math.random() - 0.5) * 30
    });
  }

  if (Math.random() < 0.035) {
    G.pickups.push({
      kind: "health", x: e.x + 8, y: e.y - 4,
      value: 18, phase: Math.random() * 7, vx: 0, vy: 0
    });
  }

  if (e.boss) {
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * Math.PI * 2 + 0.3;
      spawnGear(e.x + Math.cos(angle) * 46, e.y + Math.sin(angle) * 30, "boss");
    }
    return;
  }

  const chance = e.elite ? 1 : 0.055 + clamp(luck, 0, 120) * 0.0011;
  if (Math.random() < chance) {
    spawnGear(e.x, e.y, e.elite ? "elite" : "normal");
  }
  if (e.elite && Math.random() < 0.38) {
    spawnGear(e.x + 16, e.y + 8, "elite");
  }
}

export function collectGear(loot) {
  const item = loot.item;
  if (!item) return false;
  if (G.bag.length >= BAG_SIZE && G.equipment[item.slot]) {
    showToast("Your satchel is full. Salvage a relic first.");
    sound.error();
    return false;
  }
  const comparison = comparisonFor(item, G.equipment, G.boons);
  let autoEquipped = false;
  if (!G.equipment[item.slot]) {
    G.equipment[item.slot] = item;
    recalcStats();
    autoEquipped = true;
  } else {
    G.bag.push(item);
  }
  G.relics++;
  lootToast(item, comparison);
  sound.pickup(item.rarity);
  burst(loot.x, loot.y, item.color, item.rarity === "legendary" ? 26 : 12, item.rarity === "legendary" ? 120 : 65, 2.2, 0.8, { glow: true });
  if (item.rarity === "legendary") {
    screenShake(3.5);
    addEffect({ kind: "ring", x: loot.x, y: loot.y, radius: 110, life: 0.9, rgb: "255,139,66", alpha: 0.65, width: 3 });
  }
  if (autoEquipped) {
    showToast(`${item.name} equipped.`);
  }
  return true;
}

export function collectPickup(pickup) {
  if (pickup.kind === "xp") return { xp: pickup.value };
  if (pickup.kind === "gold") {
    const amount = Math.max(1, Math.round(pickup.value * (G.stats?.goldGain || 1)));
    G.gold += amount;
    sound.coin();
    burst(pickup.x, pickup.y, "#e1b965", 5, 35, 1.3, 0.35, { glow: true });
    return { gold: amount };
  }
  if (pickup.kind === "health") {
    const p = G.player;
    if (!p || p.hp >= G.stats.maxHp) return { health: 0 };
    const amount = Math.min(G.stats.maxHp - p.hp, pickup.value);
    p.hp += amount;
    sound.heal();
    burst(pickup.x, pickup.y, "#d74758", 8, 45, 1.5, 0.45, { glow: true });
    return { health: amount };
  }
  return {};
}

export function makeCorpseBurst(e, damage) {
  addDecal(e.x, e.y, e.boss ? 2.2 : e.elite ? 1.5 : 1, e.type === "wraith" ? "39,56,75" : "74,16,23", e.type === "wraith" ? 0.12 : 0.22);
  burst(e.x, e.y, e.type === "wraith" ? "#72b9c3" : "#8b2029", e.boss ? 55 : e.elite ? 24 : 10, e.boss ? 230 : 95, e.boss ? 4 : 2, 0.65, { glow: true, gravity: 40 });
  for (let i = 0; i < (e.boss ? 9 : 3); i++) {
    spawnParticle(e.x + (Math.random() - 0.5) * 20, e.y, (Math.random() - 0.5) * 40, -30 - Math.random() * 50, 0.9, 2 + Math.random() * 2, "#6c2440", { kind: "smoke", drag: 0.95 });
  }
  if (e.boss) {
    addEffect({ kind: "explosion", x: e.x, y: e.y, radius: 260, life: 1.5 });
    addEffect({ kind: "ring", x: e.x, y: e.y, radius: 300, life: 1.4, rgb: "255,91,78", alpha: 0.8, width: 5 });
    screenShake(14);
  }
}

import { G, WORLD, TAU, clamp, angleDiff } from "./state.js";
import { WEAPON_STYLES } from "./data.js";
import { sound } from "./audio-instance.js";
import { spawnEnemyRewards, makeCorpseBurst } from "./drops.js";
import {
  burst, damageText, addEffect, screenShake, screenFlash, spawnParticle
} from "./fx.js";
import { showAnnouncement } from "./ui.js";

export function nearestEnemy(range = 9999, x = G.player.x, y = G.player.y) {
  let best = null;
  let bestD = range * range;
  for (const e of G.enemies) {
    if (e.dead) continue;
    const d = (e.x - x) ** 2 + (e.y - y) ** 2;
    if (d < bestD) { bestD = d; best = e; }
  }
  return best;
}

function rollCrit() {
  return Math.random() < G.stats.critChance;
}

export function updatePlayerAttack(dt) {
  const p = G.player;
  p.attackCd -= dt;
  if (p.attackCd > 0) return;
  const weapon = G.equipment.weapon;
  if (!weapon?.weapon) return;
  const style = WEAPON_STYLES[weapon.weapon.style];
  const target = nearestEnemy(style.id === "scythe" ? 230 : 900);
  if (!target) return;
  fireWeapon(target, weapon, style);
}

function fireWeapon(target, weapon, style) {
  const p = G.player;
  const stats = G.stats;
  const angle = Math.atan2(target.y - p.y, target.x - p.x);
  p.facing = angle;
  p.attackAnim = 0.22;
  p.attackCd = style.cooldown / (1 + stats.attackSpeedPct);
  const base = (weapon.weapon.min + weapon.weapon.max) / 2;
  const damage = base * (1 + stats.damagePct);

  if (style.id === "scythe") {
    const area = 1 + stats.areaPct + stats.projBonus * 0.09;
    const range = style.range * area;
    const arc = style.arc * (1 + stats.areaPct * 0.12);
    let hit = 0;
    for (const e of G.enemies) {
      if (e.dead) continue;
      const d = Math.hypot(e.x - p.x, e.y - p.y);
      if (d > range + e.radius) continue;
      const a = Math.atan2(e.y - p.y, e.x - p.x);
      if (Math.abs(angleDiff(a, angle)) > arc / 2) continue;
      dealDamage(e, damage, { crit: rollCrit(), source: "weapon" });
      hit++;
      if (hit > 16) break;
    }
    addEffect({
      kind: "slash", x: p.x, y: p.y, angle,
      range, arc, life: 0.22
    });
    for (let i = 0; i < 8; i++) {
      const a = angle + (Math.random() - 0.5) * arc;
      spawnParticle(
        p.x + Math.cos(a) * (range * 0.55), p.y + Math.sin(a) * (range * 0.55),
        Math.cos(a) * 110, Math.sin(a) * 110,
        0.25, 1.6, "#e6535d", { glow: true, drag: 0.86 }
      );
    }
    screenShake(1.1);
    sound.shoot("scythe");
    return;
  }

  const count = Math.max(1, (style.count || 1) + stats.projBonus);
  const spread = style.spread || 0.1;
  const targets = G.enemies.filter(e => !e.dead);
  for (let i = 0; i < count; i++) {
    const offset = count === 1 ? 0 : (i - (count - 1) / 2) * spread;
    let aim = target;
    if (style.id === "wand" && targets.length > 1 && i > 0) {
      aim = targets[Math.floor(Math.random() * targets.length)] || target;
    }
    const shotAngle = Math.atan2(aim.y - p.y, aim.x - p.x) + offset;
    const crit = rollCrit();
    const speed = style.speed;
    G.projectiles.push({
      type: style.id,
      x: p.x + Math.cos(shotAngle) * 18,
      y: p.y + Math.sin(shotAngle) * 18,
      vx: Math.cos(shotAngle) * speed,
      vy: Math.sin(shotAngle) * speed,
      r: style.id === "wand" ? 6 : 5,
      damage,
      crit,
      life: style.id === "wand" ? 1.8 : 1.25,
      hitsLeft: (style.id === "crossbow" ? 1 : style.id === "daggers" ? (style.pierce || 0) : 0) + 1,
      hit: new Set(),
      homing: style.homing || 0,
      target: style.id === "wand" ? aim : null,
      color: style.color
    });
  }
  if (stats.flags.soulsplit && Math.random() < stats.flags.soulsplit) {
    const echoAngle = angle + (Math.random() - 0.5) * 0.22;
    G.projectiles.push({
      type: style.id,
      x: p.x, y: p.y,
      vx: Math.cos(echoAngle) * style.speed,
      vy: Math.sin(echoAngle) * style.speed,
      r: 5, damage: damage * 0.65, crit: rollCrit(), life: 1.1, hitsLeft: 1,
      hit: new Set(), homing: style.homing || 0, target, color: style.color, echo: true
    });
  }
  const muzzleX = p.x + Math.cos(angle) * 24;
  const muzzleY = p.y + Math.sin(angle) * 24;
  burst(muzzleX, muzzleY, style.color, 5, 55, 1.6, 0.3, { glow: true });
  screenShake(0.5);
  sound.shoot(style.id);
}

export function updateProjectiles(dt) {
  const p = G.player;
  for (const proj of G.projectiles) {
    proj.life -= dt;
    if (proj.homing) {
      if (!proj.target || proj.target.dead) proj.target = nearestEnemy(500, proj.x, proj.y);
      if (proj.target) {
        const desired = Math.atan2(proj.target.y - proj.y, proj.target.x - proj.x);
        const current = Math.atan2(proj.vy, proj.vx);
        const diff = angleDiff(desired, current);
        const turn = clamp(diff, -proj.homing * dt, proj.homing * dt);
        const speed = Math.hypot(proj.vx, proj.vy);
        proj.vx = Math.cos(current + turn) * speed;
        proj.vy = Math.sin(current + turn) * speed;
      }
    }
    proj.x += proj.vx * dt;
    proj.y += proj.vy * dt;
    if (proj.x < 0 || proj.x > WORLD || proj.y < 0 || proj.y > WORLD) proj.life = -1;
    if (proj.life <= 0) continue;

    for (const e of G.enemies) {
      if (e.dead || proj.hit.has(e)) continue;
      if (Math.hypot(e.x - proj.x, e.y - proj.y) > e.radius + proj.r) continue;
      proj.hit.add(e);
      dealDamage(e, proj.damage, { crit: proj.crit, source: "weapon" });
      burst(proj.x, proj.y, proj.type === "wand" ? "#c4a4ff" : "#ffd7a2", 7, 75, 1.6, 0.35, { glow: true });
      proj.hitsLeft--;
      if (proj.hitsLeft <= 0) {
        proj.life = -1;
        break;
      }
    }
  }
  G.projectiles = G.projectiles.filter(proj => proj.life > 0 && !proj.dead);
}

export function dealDamage(e, amount, opts = {}) {
  if (!e || e.dead) return 0;
  const stats = G.stats;
  let dmg = amount;
  if (opts.crit) dmg *= stats.critDamage;
  if (stats.flags.reapersdue && e.hp / e.maxHp < 0.35) {
    dmg *= 1 + stats.flags.reapersdue;
  }
  dmg = Math.max(1, Math.round(dmg));
  e.hp -= dmg;
  e.hitFlash = 0.1;
  damageText(e.x, e.y - e.radius * 0.5, dmg, opts.crit ? "#ffd18b" : "#f3e4ce", opts.crit);
  if (opts.crit) {
    burst(e.x, e.y, "#ffbe6d", 12, 120, 2.2, 0.5, { glow: true });
    screenShake(1.6);
  } else {
    burst(e.x, e.y, "#b53b42", 4, 55, 1.3, 0.28, { glow: true });
  }
  if (stats.lifesteal > 0 && opts.allowLifesteal !== false) {
    const heal = dmg * stats.lifesteal;
    if (G.player.hp < stats.maxHp) {
      G.player.hp = Math.min(stats.maxHp, G.player.hp + heal);
    }
  }
  if (opts.silent !== true && (opts.crit || Math.random() < 0.35)) sound.hit(opts.crit);
  if (e.hp <= 0) killEnemy(e, opts.source || "weapon");
  return dmg;
}

function killEnemy(e, source) {
  if (e.dead) return;
  e.dead = true;
  G.kills++;
  const stats = G.stats;
  spawnEnemyRewards(e);
  makeCorpseBurst(e, source);
  sound.enemyDie();
  if (e.elite) screenShake(2.2);
  if (stats.flags.nightfeast) {
    G.player.hp = Math.min(stats.maxHp, G.player.hp + stats.maxHp * stats.flags.nightfeast);
  }
  if (stats.flags.gravebloom && !e.boss) {
    const radius = 78;
    addEffect({ kind: "explosion", x: e.x, y: e.y, radius, life: 0.45 });
    const weapon = G.equipment.weapon;
    const avg = weapon?.weapon ? (weapon.weapon.min + weapon.weapon.max) / 2 : 8;
    const blast = avg * (1 + stats.damagePct) * stats.flags.gravebloom;
    for (const other of G.enemies) {
      if (other.dead || other === e) continue;
      if (Math.hypot(other.x - e.x, other.y - e.y) < radius + other.radius) {
        dealDamage(other, blast, { source: "gravebloom" });
      }
    }
  }
  if (e.boss) {
    G.victoryPending = 2.8;
    G.player.invuln = 99;
    showAnnouncement("THE CROWN FALLS", "THE HOLLOW KING IS SLAIN", "Dawn bleeds through the trees.", true);
    sound.boss();
    screenShake(15);
    screenFlash(0.8);
  }
}

export function playerTakeDamage(raw, source = null, opts = {}) {
  const p = G.player;
  if (!p || p.invuln > 0 || p.dashTime > 0) return false;
  const stats = G.stats;
  const reduced = raw * (1 - Math.min(0.72, stats.armor / (stats.armor + 115)));
  const dmg = Math.max(1, Math.round(reduced));
  p.hp -= dmg;
  p.invuln = 0.55;
  damageText(p.x, p.y - 26, `-${dmg}`, "#ef777b", false);
  screenFlash(0.45);
  screenShake(5.5);
  sound.hurt();
  burst(p.x, p.y - 5, "#b72b38", 10, 85, 2, 0.45, { glow: true });
  if (stats.thorns > 0 && source && !source.dead) {
    dealDamage(source, stats.thorns, { allowLifesteal: false, source: "thorns" });
  }
  if (stats.flags.thornreflect > 0 && source && !source.dead) {
    dealDamage(source, dmg * stats.flags.thornreflect, { allowLifesteal: false, source: "thorns" });
  }
  if (p.hp <= 0) {
    p.hp = 0;
    G.pendingDeath = true;
  }
  return true;
}

export function playerDash() {
  const p = G.player;
  if (!p || G.mode !== "playing") return false;
  if (p.dashCd > 0) return false;
  let dx = G.input?.x || 0;
  let dy = G.input?.y || 0;
  if (Math.hypot(dx, dy) < 0.1) {
    dx = Math.cos(p.facing);
    dy = Math.sin(p.facing);
  }
  const len = Math.hypot(dx, dy) || 1;
  p.dashDirX = dx / len;
  p.dashDirY = dy / len;
  p.dashTime = 0.17;
  p.dashCd = 3.2 * (1 - G.stats.dashCdPct);
  p.invuln = Math.max(p.invuln, 0.38);
  p.facing = Math.atan2(p.dashDirY, p.dashDirX);
  if (G.stats.flags.windrunner) p.windrunnerTime = 2.5;
  if (G.stats.flags.voiddash) p.voidDash = true;
  sound.dash();
  burst(p.x, p.y, "#a94650", 12, 90, 1.8, 0.45, { glow: true });
  addEffect({ kind: "ring", x: p.x, y: p.y, radius: 48, life: 0.4, rgb: "180,75,82", alpha: 0.6, width: 2 });
  return true;
}

export function playerNova() {
  const p = G.player;
  if (!p || G.mode !== "playing") return false;
  if (p.novaCd > 0) return false;
  const stats = G.stats;
  const radius = 182 * (1 + stats.areaPct);
  const weapon = G.equipment.weapon;
  const avg = weapon?.weapon ? (weapon.weapon.min + weapon.weapon.max) / 2 : 12;
  const damage = avg * 4.35 * (1 + stats.damagePct) * (1 + stats.novaDmgPct);
  p.novaCd = 14 * (1 - stats.novaCdPct);
  addEffect({ kind: "nova", x: p.x, y: p.y, radius, life: 0.85 });
  addEffect({ kind: "ring", x: p.x, y: p.y, radius: radius * 1.05, life: 0.62, rgb: "255,116,103", alpha: 0.55, width: 4 });
  addEffect({ kind: "ring", x: p.x, y: p.y, radius: radius * 0.72, life: 0.48, rgb: "255,211,184", alpha: 0.35, width: 2 });
  for (const e of G.enemies) {
    if (e.dead) continue;
    if (Math.hypot(e.x - p.x, e.y - p.y) < radius + e.radius) {
      dealDamage(e, damage, { crit: rollCrit(), source: "nova" });
    }
  }
  burst(p.x, p.y, "#e3454c", 45, 260, 3.2, 0.85, { glow: true, drag: 0.9 });
  for (let i = 0; i < 18; i++) {
    const a = Math.random() * TAU;
    const r = 25 + Math.random() * radius;
    spawnParticle(
      p.x + Math.cos(a) * r, p.y + Math.sin(a) * r,
      Math.cos(a) * 120, Math.sin(a) * 120,
      0.5, 2.2, "#ff8a78", { glow: true, drag: 0.88 }
    );
  }
  screenShake(9);
  screenFlash(0.4);
  sound.nova();
  return true;
}

export function updateEnemies(dt) {
  const p = G.player;
  const stats = G.stats;
  for (const e of G.enemies) {
    if (e.dead) continue;
    e.hitFlash = Math.max(0, e.hitFlash - dt);
    e.attackCd = Math.max(0, e.attackCd - dt);
    e.shootFlash = Math.max(0, (e.shootFlash || 0) - dt);
    e.phase += dt * (e.type === "bat" ? 4 : 1);
    e.facing = Math.atan2(p.y - e.y, p.x - e.x);
    const dx = p.x - e.x;
    const dy = p.y - e.y;
    const d = Math.hypot(dx, dy) || 1;

    if (e.boss) {
      updateBoss(e, dt, d, dx, dy);
      continue;
    }

    if (e.ranged) {
      const desired = e.type === "skeleton" ? 285 : 235;
      if (d > desired + 25) {
        e.x += (dx / d) * e.speed * dt;
        e.y += (dy / d) * e.speed * dt;
      } else if (d < desired - 75) {
        e.x -= (dx / d) * e.speed * 0.75 * dt;
        e.y -= (dy / d) * e.speed * 0.75 * dt;
      } else {
        e.x += Math.cos(e.phase * 0.5 + e.phase) * 12 * dt;
        e.y += Math.sin(e.phase * 0.5) * 12 * dt;
      }
      e.shootCd -= dt;
      if (e.shootCd <= 0 && d < 500) {
        e.shootCd = e.type === "skeleton" ? 2.25 : 2.7;
        e.shootFlash = 0.18;
        shootAtPlayer(e, e.type === "skeleton" ? "bone" : "soul", 250);
      }
    } else {
      const speed = e.speed * (e.type === "bat" ? 1 + Math.sin(e.phase * 2.2) * 0.12 : 1);
      e.x += (dx / d) * speed * dt;
      e.y += (dy / d) * speed * dt;
      if (e.type === "bat") {
        e.x += Math.cos(e.phase * 2.6) * 28 * dt;
        e.y += Math.sin(e.phase * 2.1) * 28 * dt;
      }
      if (d < e.radius + p.radius + 3 && e.attackCd <= 0) {
        e.attackCd = 0.95;
        playerTakeDamage(e.damage, e);
        if (G.pendingDeath) return;
      }
    }
    e.x = clamp(e.x, 24, WORLD - 24);
    e.y = clamp(e.y, 24, WORLD - 24);
  }
  G.enemies = G.enemies.filter(e => !e.dead);
}

function updateBoss(e, dt, d, dx, dy) {
  const p = G.player;
  e.facing = Math.atan2(dy, dx);
  if (d > 105) {
    e.x += (dx / d) * e.speed * dt;
    e.y += (dy / d) * e.speed * dt;
  } else if (d < 65) {
    e.x -= (dx / d) * e.speed * 0.5 * dt;
    e.y -= (dy / d) * e.speed * 0.5 * dt;
  }
  e.patternCd -= dt;
  e.summonCd -= dt;
  if (e.patternCd <= 0) {
    e.patternCd = e.enraged ? 2.9 : 3.8;
    const count = e.enraged ? 18 : 12;
    const offset = Math.random() * TAU;
    for (let i = 0; i < count; i++) {
      const angle = offset + (i / count) * TAU;
      shootProjectile(e.x, e.y, angle, 170, 12, "soul", 7);
    }
    addEffect({ kind: "ring", x: e.x, y: e.y, radius: 120, life: 0.7, rgb: "206,61,64", alpha: 0.5, width: 3 });
    sound.tone({ freq: 94, dur: 0.5, type: "sine", vol: 0.06, slide: 0.7 });
    screenShake(3);
  }
  if (e.summonCd <= 0) {
    e.summonCd = e.enraged ? 6.5 : 8.5;
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * TAU + Math.random();
      spawnMinion(e.x + Math.cos(angle) * 60, e.y + Math.sin(angle) * 60, e.enraged ? "wraith" : "bat");
    }
    addEffect({ kind: "explosion", x: e.x, y: e.y, radius: 90, life: 0.5 });
  }
  if (d < e.radius + p.radius + 6 && e.attackCd <= 0) {
    e.attackCd = 1.1;
    playerTakeDamage(e.damage, e);
  }
}

function shootAtPlayer(e, color, speed) {
  const angle = Math.atan2(G.player.y - e.y, G.player.x - e.x);
  shootProjectile(e.x + Math.cos(angle) * 15, e.y + Math.sin(angle) * 15, angle, speed, color === "bone" ? 8 : 11, color, color === "bone" ? 4 : 6);
  sound.tone({ freq: color === "bone" ? 380 : 240, dur: 0.1, type: "triangle", vol: 0.018, slide: 0.7 });
}

export function shootProjectile(x, y, angle, speed, damage, color = "soul", radius = 5) {
  G.foeShots.push({
    x, y,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    damage, color, r: radius,
    life: 4.2,
    phase: Math.random() * 7
  });
}

export function updateFoeShots(dt) {
  const p = G.player;
  for (const shot of G.foeShots) {
    shot.life -= dt;
    shot.x += shot.vx * dt;
    shot.y += shot.vy * dt;
    if (shot.life <= 0 || shot.x < 0 || shot.x > WORLD || shot.y < 0 || shot.y > WORLD) {
      shot.life = -1;
      continue;
    }
    if (Math.hypot(shot.x - p.x, shot.y - p.y) < p.radius + shot.r + 2) {
      if (playerTakeDamage(shot.damage, null)) {
        shot.life = -1;
        burst(shot.x, shot.y, shot.color === "bone" ? "#e4d4af" : "#e1747b", 7, 70, 1.5, 0.3, { glow: true });
      }
    }
  }
  G.foeShots = G.foeShots.filter(shot => shot.life > 0);
}

export function spawnMinion(x, y, type) {
  const base = type === "wraith" ? 74 : 14;
  G.enemies.push({
    type,
    x, y,
    hp: base * (1 + G.time * 0.004),
    maxHp: base * (1 + G.time * 0.004),
    speed: type === "wraith" ? 42 : 102,
    damage: type === "wraith" ? 12 : 5,
    radius: type === "wraith" ? 15 : 9,
    xp: type === "wraith" ? 8 : 2,
    attackCd: 0.5,
    shootCd: 1.3,
    phase: Math.random() * 10,
    hitFlash: 0,
    shootFlash: 0,
    ranged: type === "wraith",
    facing: 0
  });
}

