 const heal = Math.min(G.stats.maxHp - hp, Math.round(G.stats.maxHp * 0.35));
 ...
 return {healed, cost};
}
```
Should also be usable in paused? Inventory only.

- Reforge:
```
export function reforgeItem(item) {
 const cost = reforgeCost(item);
 if (!item) return false;
 if (G.gold < cost) ...
 const fresh = createItem({slot:item.slot,itemLevel:item.itemLevel,rarityKey:item.rarity,weaponStyle:item.weapon?.style});
