import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForSelector('#hud:not(.is-hidden)');
await page.waitForTimeout(500);

// Fast-forward to boss spawn.
await page.evaluate(() => {
  const { G } = window.__bloodmoon;
  G.time = 239.5;
});
await page.waitForTimeout(900);

const bossInfo = await page.evaluate(() => {
  const { G } = window.__bloodmoon;
  if (!G.boss) return null;
  G.boss.x = G.player.x + 175;
  G.boss.y = G.player.y - 20;
  G.boss.hp = G.boss.maxHp;
  G.boss.attackCd = 99;
  G.boss.patternCd = 99;
  G.boss.summonCd = 99;
  return { type: G.boss.type, hp: G.boss.hp, x: G.boss.x, y: G.boss.y, time: G.time };
});
console.log('boss:', bossInfo);

// Clear chaff so the king is readable in the screenshot.
await page.evaluate(() => {
  const { G } = window.__bloodmoon;
  G.enemies = G.enemies.filter(e => e.boss);
});
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/opencode/boss-upright.png' });

// Probe canvas pixels around the boss? Just report player/boss screen coords for cropping.
const geom = await page.evaluate(() => {
  const { G } = window.__bloodmoon;
  const c = document.getElementById('game');
  return { w: c.width, h: c.height, cssW: c.clientWidth, cssH: c.clientHeight, mode: G.mode, player: G.player, boss: { x: G.boss.x, y: G.boss.y }, camera: G.camera };
});
console.log('geom:', JSON.stringify(geom));
console.log('errors:', JSON.stringify(errors));
await browser.close();

