import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const results = [];
function check(name, pass, detail = '') {
  results.push({ name, pass: !!pass, detail });
  console.log(`${pass ? 'PASS' : 'FAIL'}  ${name}${detail ? ' — ' + detail : ''}`);
}

const browser = await chromium.launch({ headless: true });

/* ───────────── desktop ───────────── */
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  check('title visible', await page.locator('#title-screen').isVisible());
  await page.click('#start-btn');
  await page.waitForSelector('#hud:not(.is-hidden)');
  check('run starts', await page.evaluate(() => window.__bloodmoon.G.mode === 'playing'));

  // Movement.
  const before = await page.evaluate(() => ({ ...window.__bloodmoon.G.player }));
  await page.keyboard.down('KeyD');
  await page.waitForTimeout(450);
  await page.keyboard.up('KeyD');
  const after = await page.evaluate(() => ({ ...window.__bloodmoon.G.player }));
  check('keyboard movement', after.x > before.x + 10, `${before.x.toFixed(0)} -> ${after.x.toFixed(0)}`);

  // Inject relics + gold, then open satchel.
  const seeded = await page.evaluate(async () => {
    const { G } = window.__bloodmoon;
    const loot = await import('/js/loot.js');
    G.gold = 800;
    G.player.hp = Math.round(G.stats.maxHp * 0.4);
    const items = [
      loot.createItem({ slot: 'helm', itemLevel: 6, rarityKey: 'rare' }),
      loot.createItem({ slot: 'chest', itemLevel: 5, rarityKey: 'magic' }),
      loot.createItem({ slot: 'ring', itemLevel: 7, rarityKey: 'legendary' }),
      loot.createItem({ slot: 'boots', itemLevel: 3, rarityKey: 'common' })
    ];
    G.bag.push(...items);
    return { gold: G.gold, hp: G.player.hp, maxHp: G.stats.maxHp, names: items.map(i => i.name) };
  });
  check('relics injected', seeded.names.length === 4, seeded.names.join(', '));

  await page.click('#inventory-btn');
  await page.waitForSelector('#inventory-screen:not(.is-hidden)');
  check('inventory opens', await page.evaluate(() => window.__bloodmoon.G.mode === 'inventory'));
  check('bag renders relics', (await page.locator('#bag-grid .bag-cell.filled').count()) === 4);

  // Select first relic and reforge it.
  await page.locator('#bag-grid .bag-cell.filled').first().click();
  const reforgeBtn = page.locator('#detail-pane [data-action="reforge"]');
  check('reforge control present', await reforgeBtn.count() === 1);
  const reforgeLabel = await reforgeBtn.textContent();
  const cost = Number((reforgeLabel.match(/(\d+)g/) || [])[1]);
  const goldBefore = await page.evaluate(() => window.__bloodmoon.G.gold);
  await reforgeBtn.click();
  const afterReforge = await page.evaluate(() => ({ gold: window.__bloodmoon.G.gold, stat: window.__bloodmoon.G.stats.armor }));
  check('reforge spends gold', afterReforge.gold === goldBefore - cost, `${goldBefore} -> ${afterReforge.gold}, cost ${cost}`);

  // Mend wounds.
  const hpBefore = await page.evaluate(() => window.__bloodmoon.G.player.hp);
  const goldPreMend = await page.evaluate(() => window.__bloodmoon.G.gold);
  await page.click('#mend-btn');
  const mendState = await page.evaluate(() => ({ hp: window.__bloodmoon.G.player.hp, gold: window.__bloodmoon.G.gold }));
  check('mend heals and costs gold', mendState.hp > hpBefore && mendState.gold === goldPreMend - 30, `hp ${hpBefore}->${mendState.hp}, gold ${goldPreMend}->${mendState.gold}`);

  // Salvage commons.
  const goldPreSalvage = await page.evaluate(() => window.__bloodmoon.G.gold);
  await page.click('#salvage-commons');
  const salvageState = await page.evaluate(() => ({ gold: window.__bloodmoon.G.gold, bag: window.__bloodmoon.G.bag.length }));
  check('salvage commons adds gold', salvageState.gold > goldPreSalvage, `gold ${goldPreSalvage}->${salvageState.gold}, bag ${salvageState.bag}`);
  check('bag still renders after actions', (await page.locator('#bag-grid .bag-cell.filled').count()) === salvageState.bag);

  // Close inventory and pause flow.
  await page.click('#close-inventory');
  check('inventory closes to playing', await page.evaluate(() => window.__bloodmoon.G.mode === 'playing'));
  await page.keyboard.press('Escape');
  await page.waitForSelector('#pause-screen:not(.is-hidden)');
  check('pause opens', await page.evaluate(() => window.__bloodmoon.G.mode === 'paused'));
  await page.click('#resume-btn');
  check('resume works', await page.evaluate(() => window.__bloodmoon.G.mode === 'playing'));

  await page.screenshot({ path: '/tmp/opencode/final-desktop.png' });
  check('desktop console clean', errors.length === 0, errors.join(' | '));
  await page.close();
}

/* ───────────── mobile ───────────── */
{
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    isMobile: true,
    hasTouch: true,
    deviceScaleFactor: 2
  });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  check('mobile title fits', await page.evaluate(() => {
    const r = document.getElementById('title-screen').getBoundingClientRect();
    return r.width <= window.innerWidth && document.documentElement.scrollWidth <= window.innerWidth + 1;
  }));
  await page.click('#start-btn');
  await page.waitForSelector('#hud:not(.is-hidden)');
  await page.waitForTimeout(300);
  check('mobile no horizontal overflow', await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1));

  // Joystick drag.
  const p0 = await page.evaluate(() => ({ ...window.__bloodmoon.G.player }));
  const joy = await page.locator('#joystick').boundingBox();
