  await page.mouse.move(cx, cy);
  await page.mouse.down();
  await page.mouse.move(cx + 40, cy, { steps: 6 });
  await page.waitForTimeout(500);
  await page.mouse.up();
  const p1 = await page.evaluate(() => ({ ...window.__bloodmoon.G.player }));
  check('joystick moves player', p1.x > p0.x + 8, `${p0.x.toFixed(0)} -> ${p1.x.toFixed(0)}`);

  await page.evaluate(async () => {
    const { G } = window.__bloodmoon;
    const loot = await import('/js/loot.js');
    G.gold = 500;
    G.player.hp = Math.round(G.stats.maxHp * 0.5);
    G.bag.push(loot.createItem({ slot: 'gloves', itemLevel: 4, rarityKey: 'rare' }));
  });
  await page.click('#inventory-btn');
  await page.waitForSelector('#inventory-screen:not(.is-hidden)');
  await page.waitForTimeout(350);

  const layout = await page.evaluate(() => {
    const inv = document.getElementById('inventory-screen').getBoundingClientRect();
    const sheet = document.querySelector('.inventory-sheet').getBoundingClientRect();
    const footer = document.querySelector('.bag-footer').getBoundingClientRect();
    const mend = document.getElementById('mend-btn').getBoundingClientRect();
    return {
      invH: inv.height, sheetH: sheet.height,
      footerBottom: footer.bottom, sheetBottom: sheet.bottom,
      mendInView: mend.top >= 0 && mend.bottom <= window.innerHeight,
      footerVisible: footer.top >= 0 && footer.bottom <= window.innerHeight,
      scrollW: document.documentElement.scrollWidth, innerW: window.innerWidth
    };
  });
  check('mobile inventory footer visible', layout.footerVisible && layout.footerBottom <= layout.sheetBottom + 1, JSON.stringify(layout));
  check('mobile mend button visible', layout.mendInView);
  check('mobile inventory no overflow', layout.scrollW <= layout.innerW + 1, `${layout.scrollW}/${layout.innerW}`);

  await page.locator('#bag-grid .bag-cell.filled').first().click();
  const mobileReforge = page.locator('#detail-pane [data-action="reforge"]');
  check('mobile reforge reachable', await mobileReforge.count() === 1);
  await mobileReforge.click();
  const mobileGold = await page.evaluate(() => window.__bloodmoon.G.gold);
  check('mobile reforge works', mobileGold < 500, `gold ${mobileGold}`);

  const mHpBefore = await page.evaluate(() => window.__bloodmoon.G.player.hp);
  await page.click('#mend-btn');
  const mMend = await page.evaluate(() => ({ hp: window.__bloodmoon.G.player.hp, gold: window.__bloodmoon.G.gold }));
  check('mobile mend works', mMend.hp > mHpBefore, `hp ${mHpBefore}->${mMend.hp}, gold ${mMend.gold}`);

  await page.screenshot({ path: '/tmp/opencode/final-mobile-inventory.png', fullPage: false });
  await page.click('#close-inventory');
  await page.waitForTimeout(200);
  await page.screenshot({ path: '/tmp/opencode/final-mobile-game.png' });
  check('mobile console clean', errors.length === 0, errors.join(' | '));
  await page.close();
}

await browser.close();
const failed = results.filter(r => !r.pass);
console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
if (failed.length) process.exitCode = 1;

