.bag-cell .item-icon { position: absolute; inset: 1px; width: auto; height: auto; }
.bag-cell .cell-level { position: absolute; right: 3px; bottom: 1px; z-index: 2; color: rgba(220, 208, 188, .42); font-family: "Cinzel", serif; font-size: 6px; }
.bag-cell .upgrade-mark { position: absolute; top: 2px; right: 3px; z-index: 2; color: #75ce9e; font-size: 8px; text-shadow: 0 0 4px #000; }
.bag-cell .item-icon .tiny-icon { width: 60%; height: 60%; }
.bag-cell .empty-plus { color: #39342e; font-size: 11px; }
.bag-footer { display: flex; gap: 6px; margin-top: 14px; }
.loot-legend { display: flex; flex-wrap: wrap; gap: 11px; margin-top: 14px; color: #5f574c; font-family: "Cinzel", serif; font-size: 6px; letter-spacing: .08em; }
.equipped-label { display: block; padding: 10px 0 0; color: #675d51; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .16em; text-align: center; }
.implicit-sub { display: block; margin-top: 3px; color: #7c705f; font-size: 10px; line-height: 1.4; }
.loot-legend span::before { content: "◆"; margin-right: 3px; font-size: 5px; }
.r-common { color: var(--r-common); } .r-magic { color: var(--r-magic); } .r-rare { color: var(--r-rare); } .r-legendary { color: var(--r-legendary); }

.detail-pane {
  display: flex;
  flex-direction: column;
  border-left: 1px solid rgba(195, 160, 99, .15);
  padding-left: 25px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #3e352b transparent;
}
.empty-detail { display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100%; text-align: center; color: #5f574d; }
.empty-sigil { display: grid; place-items: center; width: 50px; height: 50px; margin-bottom: 15px; border: 1px solid rgba(195, 160, 99, .16); border-radius: 50%; color: #75613f; font-size: 19px; }
.empty-detail p { margin: 0; font-size: 13px; }
.empty-detail small { margin-top: 5px; color: #4c453e; font-size: 9px; }

.item-card { --rarity: var(--r-common); }
.item-card-head { display: flex; align-items: flex-start; gap: 13px; }
.item-hero {
  --rarity: var(--r-common);
  width: 66px;
  height: 66px;
  flex: none;
  border: 1px solid color-mix(in srgb, var(--rarity) 46%, transparent);
  background: radial-gradient(circle at 50% 55%, color-mix(in srgb, var(--rarity) 18%, transparent), #0b090d 66%);
  box-shadow: inset 0 0 25px color-mix(in srgb, var(--rarity) 8%, transparent);
}
.item-hero .item-icon { width: 100%; height: 100%; }
.item-title-wrap { min-width: 0; padding-top: 2px; }
.item-name { margin: 0; color: var(--rarity); font-family: "Cinzel", serif; font-size: 17px; font-weight: 700; line-height: 1.18; letter-spacing: .015em; }
.item-sub { margin: 4px 0 0; color: #7b7062; font-size: 10px; }
.item-power { margin-top: 8px; color: #84765f; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .12em; }
.item-power b { color: #c3ab7b; font-weight: 400; }
.item-divider { height: 1px; margin: 15px 0 12px; background: linear-gradient(90deg, rgba(195, 160, 99, .35), transparent); }
.item-implicit { color: #d7cbb6; font-size: 12px; }
.item-implicit strong { color: #f0dfbd; font-weight: 400; }
.affix-list { display: flex; flex-direction: column; gap: 7px; margin: 11px 0 0; }
.affix { color: #78c69b; font-size: 11px; line-height: 1.35; }
.affix b { color: #a4e2bd; font-weight: 400; }
.legendary-power { margin-top: 15px; padding: 11px 12px; border-left: 2px solid var(--r-legendary); background: linear-gradient(90deg, rgba(255, 139, 66, .08), transparent); }
.legendary-power em { display: block; margin-bottom: 3px; color: var(--r-legendary); font-family: "Cinzel", serif; font-size: 7px; font-style: normal; letter-spacing: .15em; }
.legendary-power p { margin: 0; color: #d7a479; font-size: 11px; line-height: 1.4; }
.item-flavor { margin-top: 13px; color: #77695b; font-size: 10px; font-style: italic; line-height: 1.45; }
.compare-block { margin-top: 18px; padding-top: 14px; border-top: 1px solid rgba(195, 160, 99, .17); }
.compare-block h4 { margin: 0 0 7px; color: #8e806d; font-family: "Cinzel", serif; font-size: 7px; font-weight: 400; letter-spacing: .18em; }
.compare-equipped { overflow: hidden; color: var(--rarity); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.compare-stats { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; }
.compare-line { display: flex; justify-content: space-between; font-size: 9px; color: #746a5e; }
.compare-line .buff { color: #79cd9c; }
.compare-line .nerf { color: #c17779; }
.compare-summary { display: flex; align-items: center; justify-content: space-between; margin-top: 12px; padding-top: 9px; border-top: 1px solid rgba(255, 255, 255, .05); }
.compare-summary span { color: #888073; font-family: "Cinzel", serif; font-size: 7px; letter-spacing: .12em; }
.compare-summary strong { font-family: "Cinzel", serif; font-size: 13px; font-weight: 400; }
.compare-summary strong.up { color: #7cd19f; }
.compare-summary strong.down { color: #bf7477; }
