.btn-salvage:hover { border-color: #b55a52; color: #e6aaa1; background: rgba(166, 60, 52, .08); }
.sheet-foot { display: flex; justify-content: center; gap: 28px; padding: 10px 15px 13px; border-top: 1px solid rgba(195, 160, 99, .13); color: #5f574c; font-size: 9px; letter-spacing: .03em; }
.sheet-foot kbd { margin-right: 4px; }

/* ── pause / how / end ──────────────────────────────────────────────────── */
.pause-wrap { position: relative; width: min(470px, 100%); text-align: center; }
.pause-wrap .kicker { color: #8d474b; }
.pause-wrap h2 { margin-top: 7px; font-size: 54px; }
.pause-rule { width: 110px; height: 1px; margin: 20px auto 25px; background: linear-gradient(90deg, transparent, var(--gold), transparent); }
.pause-stats { display: flex; justify-content: center; gap: 35px; margin-bottom: 30px; }
.pause-stats div { display: flex; flex-direction: column; gap: 4px; }
.pause-stats span { color: #665e53; font-size: 9px; }
.pause-stats strong { color: #c2b199; font-family: "Cinzel", serif; font-size: 16px; font-weight: 400; }
.pause-actions { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.pause-actions .btn { width: 235px; }
.screen-flash.hit { animation: hit-flash .34s ease-out; }
@keyframes hit-flash { 0% { opacity: .8; } 100% { opacity: 0; } }

/* ── responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .sheet-body { grid-template-columns: 260px minmax(300px, 1fr) 308px; gap: 16px; padding: 20px 20px 14px; }
  .sheet-head { padding: 21px 23px 17px; }
  .detail-pane { padding-left: 17px; }
