import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(500);
await page.evaluate(async () => {
  const { G } = window.__bloodmoon;
  const loot = await import('/js/loot.js');
  G.gold = 500;
  G.player.hp = Math.round(G.stats.maxHp * 0.5);
  for (let i = 0; i < 8; i++) G.bag.push(loot.createItem({ slot: ['helm','chest','boots','amulet','ring'][i%5], itemLevel: 4 + i, rarityKey: ['common','magic','rare','legendary'][i%4] }));
});
await page.click('#inventory-btn');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/mobile-top.png' });
await page.locator('.bag-cell.filled').first().click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/mobile-selected.png' });
await page.evaluate(() => { document.querySelector('#inventory-screen .sheet').scrollTop = 9999; });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/mobile-bottom.png' });
const layout = await page.evaluate(() => {
  const rect = s => { const r = document.querySelector(s).getBoundingClientRect(); return { top: r.top, bottom: r.bottom, left: r.left, right: r.right, h: r.height }; };
  const sheet = document.getElementById('inventory-screen').querySelector('.sheet');
  return {
    scrollTop: sheet.scrollTop, scrollH: sheet.scrollHeight, clientH: sheet.clientHeight,
    footer: rect('.bag-footer'), detail: rect('.detail-pane'), sheet: rect('.sheet'), mend: rect('#mend-btn'),
    mendDisabled: document.getElementById('mend-btn').disabled,
    elementAtMend: (() => { const r = document.getElementById('mend-btn').getBoundingClientRect(); const e = document.elementFromPoint(r.left + r.width/2, r.top + r.height/2); return e ? e.id + '.' + e.className : null; })()
  };
});
console.log(JSON.stringify(layout, null, 2));
await browser.close();
